/**
 * LifeCare BLE → WebSocket Bridge (Optimized v3.0)
 * ──────────────────────────────────────────────────
 */

const noble = require('@abandonware/noble');
const { WebSocketServer } = require('ws');
const config = require('./config.json');

// Constants
const TARGET_ADDRESS = config.deviceAddress.toLowerCase().replace(/:/g, '');
const TARGET_NAME = config.deviceName || 'Life Care';
const SERVICE_VITAL = '180d';
const SERVICE_BATTERY = '180f';
const WS_PORT = config.wsPort || 8765;


// Colors for Terminal
const CLR = {
    reset: "\x1b[0m",
    bright: "\x1b[1m",
    dim: "\x1b[2m",
    green: "\x1b[32m",
    blue: "\x1b[34m",
    yellow: "\x1b[33m",
    red: "\x1b[31m",
    cyan: "\x1b[36m"
};

// State management
let isConnected = false;
let peripheral = null;
let reconnectDelay = config.reconnectDelay || 3000;
let rssiInterval = null;

// WS Server
const wss = new WebSocketServer({ port: WS_PORT });
const clients = new Set();

wss.on('connection', (ws) => {
    clients.add(ws);
    log('WS', `Client connected (${clients.size} total)`, CLR.cyan);
    broadcast({ type: 'status', connected: isConnected, device: TARGET_NAME, address: config.deviceAddress });
    ws.on('close', () => clients.delete(ws));
});

function broadcast(data) {
    const msg = JSON.stringify(data);
    clients.forEach(ws => { if (ws.readyState === ws.OPEN) ws.send(msg); });
}

function log(label, msg, color = CLR.reset) {
    const time = new Date().toLocaleTimeString();
    console.log(`${CLR.dim}[${time}]${CLR.reset} ${color}${CLR.bright}[${label}]${CLR.reset} ${msg}`);
}

// ── Data Parsers ──────────────────────────────────────────
function parseTemperature(buf) {
    const raw = buf.readInt16LE(0);
    const mantissa = raw & 0x0FFF;
    const exponent = raw >> 12;
    const signedMantissa = (mantissa & 0x800) ? mantissa - 0x1000 : mantissa;
    return parseFloat((signedMantissa * Math.pow(10, exponent)).toFixed(1));
}

function parseHeartRate(buf) {
    const flags = buf.readUInt8(0);
    return (flags & 0x1) ? buf.readUInt16LE(1) : buf.readUInt8(1);
}

// ── BLE Logic ─────────────────────────────────────────────
async function startScan() {
    log('BLE', `Scanning for ${CLR.bright}${TARGET_NAME}${CLR.reset} (${config.deviceAddress})...`, CLR.blue);
    broadcast({ type: 'scanning' });
    try {
        await noble.startScanningAsync([], false);
    } catch (e) {
        log('ERR', `Scan failed: ${e.message}`, CLR.red);
    }
}

noble.on('stateChange', async (state) => {
    log('SYS', `Bluetooth Adapter: ${state.toUpperCase()}`, state === 'poweredOn' ? CLR.green : CLR.yellow);
    if (state === 'poweredOn') {
        startScan();
    } else {
        noble.stopScanning();
    }
});

noble.on('discover', async (p) => {
    const addr = p.address.toLowerCase().replace(/:/g, '');
    const name = p.advertisement.localName || 'Unknown';

    if (addr === TARGET_ADDRESS || name === TARGET_NAME) {
        noble.stopScanning();
        peripheral = p;
        log('BLE', `Found device: ${CLR.bright}${name}${CLR.reset} [${p.address}] RSSI: ${p.rssi}dBm`, CLR.green);
        await connectDevice(p);
    }
});

async function connectDevice(p) {
    try {
        broadcast({ type: 'connecting' });
        log('BLE', 'Connecting...', CLR.blue);

        await p.connectAsync();
        isConnected = true;
        reconnectDelay = config.reconnectDelay || 3000; // reset backoff

        log('BLE', '✓ Connected successfully!', CLR.green);
        broadcast({ type: 'status', connected: true, rssi: p.rssi });

        const { characteristics } = await p.discoverSomeServicesAndCharacteristicsAsync(
            [SERVICE_VITAL, SERVICE_BATTERY],
            []
        );

        for (const char of characteristics) {
            const uuid = char.uuid.toLowerCase();

            // Battery Level (180F -> 2A19)
            if (uuid === '2a19') {
                try {
                    await char.subscribeAsync();
                    const initialBat = await char.readAsync();
                    broadcast({ type: 'battery', value: initialBat.readUInt8(0) });

                    char.on('data', (data) => {
                        const val = data.readUInt8(0);
                        log('BAT', `${val}%`, CLR.green);
                        broadcast({ type: 'battery', value: val });
                    });
                } catch (e) { log('ERR', `Battery setup failed: ${e.message}`, CLR.red); }
            }

            // Heart Rate
            if (uuid === '2a37') {
                await char.subscribeAsync();
                char.on('data', (data) => {
                    const val = parseHeartRate(data);
                    log('HR', `${val} bpm`, CLR.red);
                    broadcast({ type: 'vital', key: 'hr', value: val });
                });
            }
            // Temp
            if (uuid === '2a6e') {
                await char.subscribeAsync();
                char.on('data', (data) => {
                    const val = parseTemperature(data);
                    log('TEMP', `${val} °C`, CLR.yellow);
                    broadcast({ type: 'vital', key: 'temp', value: val });
                });
            }
            // SpO2
            if (uuid === '2a5f') {
                await char.subscribeAsync();
                char.on('data', (data) => {
                    const val = data.readUInt8(0);
                    log('SPO2', `${val} %`, CLR.blue);
                    broadcast({ type: 'vital', key: 'spo2', value: val });
                });
            }
        }

        // Start RSSI Monitoring
        rssiInterval = setInterval(async () => {
            if (isConnected) {
                const rssi = await p.updateRssiAsync();
                broadcast({ type: 'rssi', value: rssi });
            }
        }, 5000);

        p.once('disconnect', () => {
            log('BLE', '✗ Disconnected', CLR.red);
            cleanupConnection();
            scheduleReconnect();
        });

    } catch (err) {
        log('ERR', `Connection failed: ${err.message}`, CLR.red);
        cleanupConnection();
        scheduleReconnect();
    }
}

function cleanupConnection() {
    isConnected = false;
    if (rssiInterval) clearInterval(rssiInterval);
    broadcast({ type: 'status', connected: false });
}

function scheduleReconnect() {
    log('SYS', `Reconnecting in ${reconnectDelay / 1000}s...`, CLR.dim);
    setTimeout(() => {
        // Exponential backoff
        reconnectDelay = Math.min(reconnectDelay * 1.5, 30000);
        if (noble.state === 'poweredOn') startScan();
    }, reconnectDelay);
}

// Graceful Shutdown
process.on('SIGINT', () => {
    log('SYS', 'Shutting down bridge...', CLR.yellow);
    noble.stopScanning();
    if (peripheral) peripheral.disconnect();
    process.exit();
});

console.log(`\n${CLR.cyan}${CLR.bright}LifeCare Backend Bridge v3.0 Online${CLR.reset}`);
console.log(`${CLR.dim}Target: ${TARGET_NAME} (${config.deviceAddress})${CLR.reset}\n`);

import js from '@eslint/js'
import globals from 'globals'
import reactHooks from 'eslint-plugin-react-hooks'
import reactRefresh from 'eslint-plugin-react-refresh'
import { defineConfig, globalIgnores } from 'eslint/config'

export default defineConfig([
  { ignores: ['dist/**', 'backend/**', 'check.cjs', 'check.js', 'lint_output.txt'] },
  {
    files: ['**/*.{js,jsx}'],
    extends: [
      js.configs.recommended,
      reactHooks.configs.flat.recommended,
      reactRefresh.configs.vite,
    ],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
      parserOptions: {
        ecmaVersion: 'latest',
        ecmaFeatures: { jsx: true },
        sourceType: 'module',
      },
    },
    rules: {
      'no-unused-vars': ['warn', { varsIgnorePattern: '^[A-Z_]' }],
    },
  },
])

import { Outlet, NavLink, useNavigate, useLocation } from 'react-router-dom';
import {
    Home, Activity, Pill, UserPlus, HeartHandshake,
    FileText, Globe, LogOut, Users, Moon, Sun, User
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function MainLayout({ lang, toggleLang, role, setRole, theme, toggleTheme }) {
    const isRtl = lang === 'ar';
    const navigate = useNavigate();
    const location = useLocation();

    // Role badge info
    const roleBadge = {
        patient: { label: isRtl ? 'مريض' : 'Patient', color: 'var(--primary)' },
        caregiver: { label: isRtl ? 'مرافق' : 'Caregiver', color: 'var(--secondary)' },
        doctor: { label: isRtl ? 'طبيب' : 'Doctor', color: 'var(--accent)' },
    };

    const getNavItems = () => {
        if (role === 'doctor') {
            return [
                { name: isRtl ? 'الرئيسية' : 'Home', path: '/dashboard', icon: <Home size={22} /> },
                { name: isRtl ? 'المرضى' : 'Patients', path: '/patients', icon: <Users size={22} /> },
            ];

        } else if (role === 'caregiver') {
            return [
                { name: isRtl ? 'الرئيسية' : 'Home', path: '/dashboard', icon: <Home size={22} /> },
                { name: isRtl ? 'التقارير' : 'Reports', path: '/reports', icon: <FileText size={22} /> },
            ];
        }
        return [
            { name: isRtl ? 'الرئيسية' : 'Home', path: '/dashboard', icon: <Home size={22} /> },
            { name: isRtl ? 'الأدوية' : 'Meds', path: '/medications', icon: <Pill size={22} /> },
            { name: isRtl ? 'التقارير' : 'Reports', path: '/reports', icon: <FileText size={22} /> },
            { name: isRtl ? 'الأطباء' : 'Doctors', path: '/doctors', icon: <UserPlus size={22} /> },
            { name: isRtl ? 'العائلة' : 'Family', path: '/caregivers', icon: <HeartHandshake size={22} /> },
        ];
    };

    const navItems = getNavItems();
    const badge = roleBadge[role] || roleBadge.patient;

    const handleLogout = () => {
        setRole(null);
        navigate('/welcome');
    };

    return (
        <>
            {/* ── Header ── */}
            <header className="mobile-header" style={{ borderBottom: '1px solid var(--glass-border)' }}>
                <div className="flex items-center gap-sm">
                    <div style={{
                        background: 'linear-gradient(135deg,var(--primary-dark),var(--primary-light))',
                        padding: '8px 10px', borderRadius: 14, display: 'flex',
                        boxShadow: '0 4px 12px rgba(16,185,129,0.3)'
                    }}>
                        <Activity color="white" size={18} />
                    </div>
                    <div className="flex flex-col" style={{ gap: 1 }}>
                        <span style={{ fontWeight: 800, color: 'var(--primary)', fontSize: '1rem', lineHeight: 1 }}>
                            LifeCare
                        </span>
                        <span style={{
                            fontSize: '0.65rem', fontWeight: 600, color: 'white',
                            background: badge.color, padding: '2px 8px', borderRadius: 20, width: 'fit-content'
                        }}>
                            {badge.label}
                        </span>
                    </div>
                </div>

                <div className="flex items-center gap-sm">
                    <button
                        onClick={() => navigate('/profile')}
                        style={{
                            background: 'var(--glass-bg)', border: '1px solid var(--glass-border)',
                            borderRadius: 12, width: 36, height: 36, display: 'flex',
                            alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                            color: 'var(--text-main)', boxShadow: '0 2px 8px rgba(0,0,0,0.06)'
                        }}
                    >
                        <User size={17} />
                    </button>
                    <button
                        onClick={toggleTheme}
                        style={{
                            background: 'var(--glass-bg)', border: '1px solid var(--glass-border)',
                            borderRadius: 12, width: 36, height: 36, display: 'flex',
                            alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                            color: 'var(--text-main)', boxShadow: '0 2px 8px rgba(0,0,0,0.06)'
                        }}
                    >
                        {theme === 'dark' ? <Sun size={17} /> : <Moon size={17} />}
                    </button>
                    <button
                        onClick={toggleLang}
                        style={{
                            background: 'var(--glass-bg)', border: '1px solid var(--glass-border)',
                            borderRadius: 12, width: 36, height: 36, display: 'flex',
                            alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                            color: 'var(--text-main)', boxShadow: '0 2px 8px rgba(0,0,0,0.06)'
                        }}
                    >
                        <Globe size={17} />
                    </button>
                    <button
                        onClick={handleLogout}
                        style={{
                            background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.2)',
                            borderRadius: 12, width: 36, height: 36, display: 'flex',
                            alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
                            color: 'var(--danger)'
                        }}
                    >
                        <LogOut size={17} />
                    </button>
                </div>
            </header>

            {/* ── Main Content ── */}
            <main className="main-content">
                <AnimatePresence mode="wait">
                    <motion.div
                        key={location.pathname}
                        initial={{ opacity: 0, y: 12 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -12 }}
                        transition={{ duration: 0.25, ease: 'easeOut' }}
                    >
                        <Outlet />
                    </motion.div>
                </AnimatePresence>
            </main>

            {/* ── Bottom Navigation ── */}
            <nav className="bottom-nav">
                {navItems.map((item, idx) => (
                    <NavLink
                        key={idx}
                        to={item.path}
                        className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
                    >
                        {item.icon}
                        <span>{item.name}</span>
                    </NavLink>
                ))}
            </nav>
        </>
    );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { HeartHandshake, PhoneCall, AlertCircle, Plus, BellRing, User, Phone, Users, CheckCircle, Copy } from 'lucide-react';

export default function Caregivers() {
    const lang = document.documentElement.lang || 'ar';
    const isRtl = lang === 'ar';

    const [caregivers, setCaregivers] = useState([
        { id: 1, name: isRtl ? 'علي أحمد' : 'Ali Ahmed', relation: isRtl ? 'ابن' : 'Son', phone: '+123456789', isPrimary: true },
        { id: 2, name: isRtl ? 'فاطمة' : 'Fatima', relation: isRtl ? 'ابنة' : 'Daughter', phone: '+987654321', isPrimary: false }
    ]);

    const [showAddForm, setShowAddForm] = useState(false);
    const [newCaregiver, setNewCaregiver] = useState({ name: '', relation: '', phone: '' });
    const [generatedCode, setGeneratedCode] = useState(null);

    const handleGenerateCode = () => {
        if (!newCaregiver.name || !newCaregiver.phone) {
            alert(isRtl ? 'يرجى إدخال الاسم ورقم الهاتف على الأقل.' : 'Please enter at least name and phone.');
            return;
        }
        // Generate a random 6 char code
        const code = 'LC-' + Math.floor(1000 + Math.random() * 9000);
        setGeneratedCode(code);
    };

    const handleCopyAndSave = () => {
        navigator.clipboard.writeText(generatedCode);
        alert(isRtl ? 'تم نسخ الكود!' : 'Code copied!');

        setCaregivers(prev => [...prev, {
            id: Date.now(),
            name: newCaregiver.name,
            relation: newCaregiver.relation || (isRtl ? 'مرافق' : 'Caregiver'),
            phone: newCaregiver.phone,
            isPrimary: false
        }]);

        setShowAddForm(false);
        setGeneratedCode(null);
        setNewCaregiver({ name: '', relation: '', phone: '' });
    };

    return (
        <div className="flex flex-col gap-lg" style={{ paddingBottom: 40 }}>
            <div className="flex flex-col gap-sm" style={{ padding: '10px 0' }}>
                <div className="flex justify-between items-center">
                    <h2 style={{ fontSize: '1.2rem', margin: 0 }}>{isRtl ? 'العائلة والمرافقين' : 'Family & Caregivers'}</h2>
                    <button className="btn-secondary flex items-center gap-sm" style={{ background: 'var(--danger)', boxShadow: '0 4px 12px rgba(250, 82, 82, 0.3)', padding: '8px 12px', fontSize: '0.85rem' }}>
                        <AlertCircle size={16} /> {isRtl ? 'طوارئ SOS' : 'SOS'}
                    </button>
                </div>
                <p className="text-sm">{isRtl ? 'إدارة جهات الاتصال الخاصة بالطوارئ.' : 'Manage your emergency contacts.'}</p>
            </div>

            <div className="flex flex-col gap-md">
                <div
                    onClick={() => setShowAddForm(true)}
                    className="glass-card flex flex-col justify-center items-center gap-md"
                    style={{ padding: 40, border: '2px dashed var(--glass-border)', cursor: 'pointer', background: 'transparent' }}
                >
                    <div style={{ background: 'var(--glass-bg)', padding: 16, borderRadius: '50%' }}>
                        <Plus size={32} color="var(--primary)" />
                    </div>
                    <h3 style={{ margin: 0, color: 'var(--primary)' }}>{isRtl ? 'إضافة فرد عائلة / مرافق' : 'Add Family Member'}</h3>
                </div>

                {caregivers.map(cg => (
                    <motion.div
                        key={cg.id}
                        whileHover={{ scale: 1.02 }}
                        className="glass-card flex flex-col justify-between"
                        style={{ padding: 24, position: 'relative', borderLeft: cg.isPrimary ? '4px solid var(--primary)' : 'none' }}
                    >
                        {cg.isPrimary && (
                            <span style={{ position: 'absolute', top: 16, right: isRtl ? 'auto' : 16, left: isRtl ? 16 : 'auto', background: 'var(--primary)20', color: 'var(--primary)', padding: '4px 12px', borderRadius: 20, fontSize: '0.8rem', fontWeight: 'bold' }}>
                                {isRtl ? 'أساسي' : 'Primary'}
                            </span>
                        )}

                        <div className="flex items-start gap-md" style={{ marginBottom: 24 }}>
                            <div style={{ background: 'var(--primary)', color: 'white', padding: 16, borderRadius: '50%' }}>
                                <HeartHandshake size={32} />
                            </div>

                            <div style={{ marginTop: 8 }}>
                                <h2 style={{ margin: 0 }}>{cg.name}</h2>
                                <span className="text-muted text-sm">{cg.relation} • {cg.phone}</span>
                            </div>
                        </div>

                        <div className="flex gap-md mt-4">
                            <button className="flex-1 flex items-center justify-center gap-sm btn-primary" style={{ padding: '12px' }}>
                                <PhoneCall size={20} /> <span className="hide-on-print">{isRtl ? 'اتصال الآن' : 'Call Now'}</span>
                            </button>
                            <button className="flex-1 flex items-center justify-center gap-sm glass-card text-warning" style={{ padding: '12px', border: 'none', cursor: 'pointer' }}>
                                <BellRing size={20} /> <span className="hide-on-print">{isRtl ? 'تنبيه' : 'Alert'}</span>
                            </button>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Modal for adding/generating code */}
            <AnimatePresence>
                {showAddForm && (
                    <>
                        <motion.div
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100dvh', background: 'rgba(0,0,0,0.5)', zIndex: 999, backdropFilter: 'blur(4px)' }}
                            onClick={() => { if (!generatedCode) setShowAddForm(false); }}
                        />
                        <motion.div
                            initial={{ opacity: 0, y: 100, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 100 }}
                            className="glass-panel"
                            style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', width: '90%', maxWidth: 400, zIndex: 1000, padding: 24, display: 'flex', flexDirection: 'column', gap: 16 }}
                        >
                            {!generatedCode ? (
                                <>
                                    <h2 style={{ margin: 0, color: 'var(--primary)', textAlign: 'center' }}>{isRtl ? 'إضافة مرافق جديد' : 'Add New Caregiver'}</h2>
                                    <p className="text-sm text-center" style={{ marginBottom: 12 }}>
                                        {isRtl ? 'أدخل بينات المرافق، وسنقوم بإنشاء رمز دخول (Code) خاص به لربط حسابه بحالتك.' : 'Enter details to generate a unique sync code for them.'}
                                    </p>

                                    <div className="flex items-center gap-sm" style={{ background: 'var(--glass-bg)', padding: '12px 16px', borderRadius: 16, border: '1px solid var(--glass-border)' }}>
                                        <User size={20} color="var(--primary)" />
                                        <input
                                            placeholder={isRtl ? 'اسم المرافق' : 'Caregiver Name'}
                                            value={newCaregiver.name} onChange={e => setNewCaregiver({ ...newCaregiver, name: e.target.value })}
                                            style={{ border: 'none', background: 'transparent', width: '100%', padding: 0, outline: 'none' }}
                                        />
                                    </div>
                                    <div className="flex items-center gap-sm" style={{ background: 'var(--glass-bg)', padding: '12px 16px', borderRadius: 16, border: '1px solid var(--glass-border)' }}>
                                        <Users size={20} color="var(--primary)" />
                                        <input
                                            placeholder={isRtl ? 'صلة القرابة (مثال: ابن، زوج)' : 'Relation'}
                                            value={newCaregiver.relation} onChange={e => setNewCaregiver({ ...newCaregiver, relation: e.target.value })}
                                            style={{ border: 'none', background: 'transparent', width: '100%', padding: 0, outline: 'none' }}
                                        />
                                    </div>
                                    <div className="flex items-center gap-sm" style={{ background: 'var(--glass-bg)', padding: '12px 16px', borderRadius: 16, border: '1px solid var(--glass-border)' }}>
                                        <Phone size={20} color="var(--primary)" />
                                        <input
                                            type="tel"
                                            placeholder={isRtl ? 'رقم الهاتف' : 'Phone Number'}
                                            value={newCaregiver.phone} onChange={e => setNewCaregiver({ ...newCaregiver, phone: e.target.value })}
                                            style={{ border: 'none', background: 'transparent', width: '100%', padding: 0, outline: 'none' }}
                                        />
                                    </div>

                                    <div className="flex gap-md" style={{ marginTop: 12 }}>
                                        <button className="btn-secondary" style={{ flex: 1, background: 'transparent', color: 'var(--text-main)', border: '1px solid var(--glass-border)', boxShadow: 'none' }} onClick={() => setShowAddForm(false)}>
                                            {isRtl ? 'إلغاء' : 'Cancel'}
                                        </button>
                                        <button className="btn-primary" style={{ flex: 1 }} onClick={handleGenerateCode}>
                                            {isRtl ? 'إنشاء رمز الربط' : 'Generate Code'}
                                        </button>
                                    </div>
                                </>
                            ) : (
                                <div className="flex flex-col items-center gap-lg">
                                    <div style={{ background: 'var(--success)20', padding: 20, borderRadius: '50%' }}>
                                        <CheckCircle size={48} color="var(--success)" />
                                    </div>

                                    <h2 style={{ margin: 0, textAlign: 'center' }}>{isRtl ? 'تم إنشاء الرمز بنجاح!' : 'Code Generated!'}</h2>
                                    <p className="text-sm text-center" style={{ lineHeight: 1.6 }}>
                                        {isRtl
                                            ? `أرسل هذا الرمز لـ "${newCaregiver.name}". يمكنه استخدامه عند إنشاء حسابه كمرافق في تطبيق LifeCare لربط بياناتك به تلقائياً.`
                                            : `Send this code to "${newCaregiver.name}". They can use it during their Caregiver registration to sync with your account.`}
                                    </p>

                                    <div className="glass-card flex items-center justify-between" style={{ padding: '16px 24px', width: '100%', border: '2px dashed var(--primary)' }}>
                                        <span style={{ fontSize: '1.5rem', fontWeight: 900, color: 'var(--primary)', letterSpacing: 2 }}>
                                            {generatedCode}
                                        </span>
                                        <button
                                            className="btn-primary"
                                            style={{ padding: '10px 16px', borderRadius: 12, display: 'flex', alignItems: 'center', gap: 8 }}
                                            onClick={handleCopyAndSave}
                                        >
                                            <Copy size={18} /> {isRtl ? 'نسخ وحفظ' : 'Copy'}
                                        </button>
                                    </div>
                                </div>
                            )}
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </div>
    );
}

