import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Activity, Droplet, Thermometer, Watch, AlertTriangle, CheckCircle, Users, Wind, Stethoscope, Calendar } from 'lucide-react';

export default function Dashboard({ role, lang }) {
    const navigate = useNavigate();
    const isRtl = lang === 'ar';
    const deviceRef = useRef(null);
    const wsRef = useRef(null);

    const [synced, setSynced] = useState(false);
    const [bluetoothActive, setBluetoothActive] = useState(false);
    const [showScanner, setShowScanner] = useState(false);
    const [scanningStep, setScanningStep] = useState('searching');
    const [connMode, setConnMode] = useState(null);
    const [connecting, setConnecting] = useState(false);
    const [connStatus, setConnStatus] = useState('scanning');
    const [connError, setConnError] = useState('');
    const [rssi, setRssi] = useState(null); // Signal strength
    const [battery, setBattery] = useState(null); // Battery percentage
    const [isAlerting, setIsAlerting] = useState(false); // Health emergency
    const [alertMsg, setAlertMsg] = useState('');


    // Empty initial vitals
    const [vitals, setVitals] = useState({
        hr: { value: '--', label: isRtl ? 'النبض' : 'Heart Rate', icon: Heart, color: 'var(--success)', status: 'normal', unit: 'bpm' },
        bp: { value: '--/--', label: isRtl ? 'الضغط' : 'Blood Pressure', icon: Activity, color: 'var(--success)', status: 'normal', unit: 'mmHg' },
        bg: { value: '--', label: isRtl ? 'السكر' : 'Glucose', icon: Droplet, color: 'var(--warning)', status: 'warning', unit: 'mg/dL' },
        temp: { value: '--', label: isRtl ? 'الحرارة' : 'Body Temp', icon: Thermometer, color: 'var(--success)', status: 'normal', unit: '°C' },
        spo2: { value: '--', label: isRtl ? 'الأكسجين' : 'Blood Oxygen', icon: Wind, color: '#339af0', status: 'normal', unit: '%' }
    });


    // ─── Persistence & Alert Monitoring ───────────────────────────
    useEffect(() => {
        // Load history from LocalStorage
        const saved = localStorage.getItem('lifeCareHistory');
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                // Simple logic to keep only last 24h (optional implementation)
                // setHistory(parsed);
            } catch (e) { console.error('History load failed'); }
        }
    }, []);

    useEffect(() => {
        if (!synced) return;

        // Critical Alert Logic
        const hrVal = parseInt(vitals.hr.value);
        const spo2Val = parseInt(vitals.spo2.value);

        if (hrVal > 140 || (spo2Val < 90 && spo2Val > 0)) {
            if (!isAlerting) {
                setIsAlerting(true);
                setAlertMsg(hrVal > 140 ? (isRtl ? 'ضربات قلب مرتفعة جداً!' : 'Critical High Heart Rate!') : (isRtl ? 'انخفاض حاد في الأكسجين!' : 'Critical Low Oxygen!'));
                // Vibrate if supported
                if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
            }
        } else {
            setIsAlerting(false);
        }

        // Cache for offline history (Last Week)
        const cacheData = { timestamp: Date.now(), hr: vitals.hr.value, temp: vitals.temp.value, spo2: vitals.spo2.value };
        let history = JSON.parse(localStorage.getItem('lifeCareHistory') || '[]');
        history.push(cacheData);

        // Keep last 7 days of readings, max 5000 records to respect LocalStorage limits
        const oneWeekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
        history = history.filter(item => item.timestamp > oneWeekAgo);
        if (history.length > 5000) {
            history = history.slice(-5000);
        }
        localStorage.setItem('lifeCareHistory', JSON.stringify(history));

    }, [vitals, synced]);


    const handleDisconnect = () => {
        setSynced(false);
        setBluetoothActive(false);
        setConnMode(null);
        setRssi(null);
        setBattery(null);
        setIsAlerting(false);
        // Close WebSocket bridge if open
        if (wsRef.current) {
            wsRef.current.onclose = null;
            wsRef.current.close();
            wsRef.current = null;
        }
        // Disconnect native BLE device if connected
        if (deviceRef.current && deviceRef.current.gatt.connected) {
            deviceRef.current.gatt.disconnect();
        }
        setVitals({
            hr: { value: '--', label: isRtl ? 'النبض' : 'Heart Rate', icon: Heart, color: 'var(--success)', status: 'normal', unit: 'bpm' },
            bp: { value: '--/--', label: isRtl ? 'الضغط' : 'Blood Pressure', icon: Activity, color: 'var(--success)', status: 'normal', unit: 'mmHg' },
            bg: { value: '--', label: isRtl ? 'السكر' : 'Glucose', icon: Droplet, color: 'var(--warning)', status: 'warning', unit: 'mg/dL' },
            temp: { value: '--', label: isRtl ? 'الحرارة' : 'Body Temp', icon: Thermometer, color: 'var(--success)', status: 'normal', unit: '°C' },
            spo2: { value: '--', label: isRtl ? 'الأكسجين' : 'Blood Oxygen', icon: Wind, color: '#339af0', status: 'normal', unit: '%' }
        });
    };




    const WS_BRIDGE_URL = 'ws://localhost:8765';

    // ── WebSocket Bridge — initiates connection & shows status overlay ──
    const connectViaBridge = () => {
        return new Promise((resolve, reject) => {
            setConnecting(true);
            setConnStatus('scanning');
            setConnError('');

            const ws = new WebSocket(WS_BRIDGE_URL);
            const timeout = setTimeout(() => {
                ws.close();
                reject(new Error('timeout'));
            }, 3000);

            ws.onopen = () => {
                clearTimeout(timeout);
                wsRef.current = ws;

                ws.onmessage = (e) => {
                    try {
                        const msg = JSON.parse(e.data);

                        if (msg.type === 'scanning') setConnStatus('scanning');
                        if (msg.type === 'connecting') setConnStatus('connecting');

                        if (msg.type === 'status') {
                            if (msg.connected) {
                                setConnStatus('connected');
                                setSynced(true);
                                setBluetoothActive(true);
                                setConnMode('ws');
                                setTimeout(() => setConnecting(false), 1200); // brief "connected" flash
                                resolve();
                            } else {
                                // Device disconnected mid-session
                                setSynced(false);
                                setConnMode(null);
                                setConnecting(false);
                                setVitals(prev => ({
                                    ...prev,
                                    hr: { ...prev.hr, value: '--' },
                                    temp: { ...prev.temp, value: '--' },
                                    spo2: { ...prev.spo2, value: '--' },
                                }));
                            }
                        }

                        if (msg.type === 'battery') setBattery(msg.value);
                        if (msg.type === 'rssi') setRssi(msg.value);

                        if (msg.type === 'vital') {
                            setVitals(prev => ({
                                ...prev,
                                [msg.key]: { ...prev[msg.key], value: msg.value, lastSync: Date.now() }
                            }));
                            // Dismiss overlay on first real data
                            if (connecting) setConnecting(false);
                        }

                    } catch (_) { }
                };

                ws.onclose = () => {
                    setSynced(false);
                    setConnMode(null);
                    setConnecting(false);
                };
            };

            ws.onerror = () => {
                clearTimeout(timeout);
                reject(new Error('no_bridge'));
            };
        });
    };

    const startScanner = () => {
        if (synced) {
            handleDisconnect();
            return;
        }
        // Open native BLE picker directly — filtered for Life Care device
        connectNativeBluetooth();
    };

    // ─── ESP32-C3 Life Care BLE Configuration ───────────────────────
    const SERVICE_UUID = 0x180D;
    const CHAR_HR = 0x2A37;   // Heart Rate
    const CHAR_TEMP = 0x2A6E;   // Temperature (IEEE-11073 SFLOAT)
    const CHAR_SPO2 = 0x2A5F;   // SpO2

    const parseHeartRate = (dv) => {
        const flags = dv.getUint8(0);
        return (flags & 0x1) ? dv.getUint16(1, true) : dv.getUint8(1);
    };

    const parseTemperature = (dv) => {
        const raw = dv.getInt16(0, true);
        const mantissa = raw & 0x0FFF;
        const exponent = raw >> 12;
        const signed = mantissa & 0x800 ? mantissa - 0x1000 : mantissa;
        const val = signed * Math.pow(10, exponent);
        return isNaN(val) ? '--' : val.toFixed(1);
    };

    const parseSpO2 = (dv) => dv.getUint8(0);

    const connectNativeBluetooth = async () => {
        if (!navigator.bluetooth) {
            setConnStatus('error');
            setConnError(isRtl
                ? 'متصفحك لا يدعم البلوتوث. يرجى استخدام Chrome أو Edge.'
                : 'Your browser does not support Web Bluetooth. Please use Chrome or Edge.');
            setConnecting(true);
            return;
        }

        try {
            // Broaden filters to ensure the device shows up in the picker
            // We search for the exact name OR devices starting with "Life" as fallback
            const device = await navigator.bluetooth.requestDevice({
                filters: [
                    { name: 'Life Care' },
                    { services: [0x180D] }
                ],
                optionalServices: [0x180D, 0x180F] // Vital Signs and Battery Services
            });


            // Close the scanner list immediately after pick
            setShowScanner(false);
            await connectToDevice(device);
        } catch (error) {
            console.error('[BLE] Request Error:', error);
            if (error.name !== 'NotFoundError') {
                setConnStatus('error');
                setConnError(isRtl ? 'تأكد من تشغيل البلوتوث وقرب الجهاز.' : 'Ensure Bluetooth is ON and device is nearby.');
                setConnecting(true);
            }
        }
    };

    const connectToDevice = async (device) => {
        let firstVitalUpdated = false;
        const dismissConnectingOverlay = () => {
            if (!firstVitalUpdated) {
                firstVitalUpdated = true;
                setConnecting(false);
            }
        };

        try {
            deviceRef.current = device;
            setConnecting(true);
            setConnStatus('connecting');
            setConnError('');

            device.addEventListener('gattserverdisconnected', onDisconnected);

            const server = await device.gatt.connect();

            // Small delay to allow GATT server to stabilize
            await new Promise(r => setTimeout(r, 600));

            setConnStatus('connecting_services'); // Internal status update
            const service = await server.getPrimaryService(SERVICE_UUID);

            // Also try to get battery service if available
            try {
                const batService = await server.getPrimaryService(0x180F);
                const batChar = await batService.getCharacteristic(0x2A19);
                const batVal = await batChar.readValue();
                setBattery(batVal.getUint8(0));
                await batChar.startNotifications();
                batChar.addEventListener('characteristicvaluechanged', (e) => {
                    setBattery(e.target.value.getUint8(0));
                });
            } catch (e) { console.warn('[BLE] Battery service not found'); }


            setConnStatus('connected');
            setSynced(true);
            setBluetoothActive(true);
            setConnMode('ble');

            // Setup all characteristics in parallel
            const charConfigs = [
                { uuid: 0x2A37, key: 'hr', parser: parseHeartRate },
                { uuid: 0x2A6E, key: 'temp', parser: parseTemperature },
                { uuid: 0x2A5F, key: 'spo2', parser: parseSpO2 }
            ];

            await Promise.allSettled(charConfigs.map(async (item) => {
                try {
                    const char = await service.getCharacteristic(item.uuid);

                    // Initial read
                    try {
                        const raw = await char.readValue();
                        const val = item.parser(raw);
                        if (val !== undefined && val !== null) {
                            setVitals(curr => ({
                                ...curr,
                                [item.key]: { ...curr[item.key], value: val, lastSync: Date.now() }
                            }));
                        }
                    } catch (e) { console.warn(`[BLE] Read failed: ${item.key}`); }

                    // Notifications
                    await char.startNotifications();
                    char.addEventListener('characteristicvaluechanged', (e) => {
                        const val = item.parser(e.target.value);
                        setVitals(curr => ({
                            ...curr,
                            [item.key]: { ...curr[item.key], value: val, lastSync: Date.now() }
                        }));
                    });
                } catch (e) { console.warn(`[BLE] Setup failed: ${item.key}`); }
            }));

            // Close overlay quickly after everything is ready
            setTimeout(() => setConnecting(false), 800);

        } catch (err) {
            console.error('[BLE] Fatal Error:', err);
            setConnStatus('error');
            setConnError(err.message || 'Connection failed');
            setConnecting(true);
        }
    };

    const onDisconnected = () => {
        setSynced(false);
        setBluetoothActive(false);
        setConnMode(null);
        setVitals(current => ({
            ...current,
            hr: { ...current.hr, value: '--', lastSync: null },
            temp: { ...current.temp, value: '--', lastSync: null },
            spo2: { ...current.spo2, value: '--', lastSync: null },
        }));
    };


    const connectSimulatedWatch = () => {
        setSynced(true);
        setBluetoothActive(false);
        setShowScanner(false);
        setVitals(prev => ({
            hr: { ...prev.hr, value: 75 },
            bp: { ...prev.bp, value: '120/80' },
            bg: { ...prev.bg, value: 95 },
            temp: { ...prev.temp, value: 36.8 },
            spo2: { ...prev.spo2, value: 98 }
        }));
    };


    // DOCTOR DASHBOARD
    if (role === 'doctor') {
        return (
            <div className="flex flex-col gap-lg">
                <div className="glass-panel" style={{ padding: 20 }}>
                    <h2 style={{ margin: 0, marginBottom: 4 }}>{isRtl ? 'مرحباً، د. سارة' : 'Welcome, Dr. Sarah'}</h2>
                    <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginBottom: 12, fontWeight: 600 }}>
                        {isRtl ? 'أخصائي أمراض القلب والأوعية الدموية' : 'Cardiologist Specialist'}
                    </p>
                    <p>{isRtl ? 'نظرة عامة على حالات مرضاك اليوم.' : 'Overview of your patients today.'}</p>
                    {/* Device Status Header (Signal & Battery) */}
                    {synced && (
                        <div className="flex justify-between items-center" style={{ marginTop: 16, background: 'var(--glass-border)', padding: '8px 12px', borderRadius: 12 }}>
                            <div className="flex items-center gap-sm">
                                <div className="flex items-end gap-[2px]" style={{ height: 14 }}>
                                    {[1, 2, 3, 4].map(bar => (
                                        <div key={bar} style={{
                                            width: 3,
                                            height: bar * 3,
                                            background: rssi && (rssi > -90 + (bar * 10)) ? 'var(--primary)' : 'var(--text-muted)',
                                            opacity: rssi && (rssi > -90 + (bar * 10)) ? 1 : 0.3,
                                            borderRadius: 1
                                        }} />
                                    ))}
                                </div>
                                <span style={{ fontSize: '0.7rem', fontWeight: 700, opacity: 0.8 }}>{isRtl ? 'الإشارة' : 'Signal'}</span>
                            </div>

                            {battery !== null && (
                                <div className="flex items-center gap-sm">
                                    <span style={{ fontSize: '0.75rem', fontWeight: 800, color: battery < 20 ? 'var(--danger)' : 'var(--text-main)' }}>{battery}%</span>
                                    <div style={{ width: 22, height: 12, border: '1.5px solid currentColor', borderRadius: 2, position: 'relative', padding: 1, color: battery < 20 ? 'var(--danger)' : 'var(--text-main)' }}>
                                        <div style={{ width: `${battery}%`, height: '100%', background: battery < 20 ? 'var(--danger)' : 'var(--primary)', borderRadius: 1 }} />
                                        <div style={{ position: 'absolute', right: -3, top: 2, width: 2, height: 4, background: 'currentColor', borderRadius: '0 1px 1px 0' }} />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>


                <div className="grid grid-cols-2">
                    <div className="glass-card flex flex-col items-center justify-center text-center p-md" style={{ padding: 16 }}>
                        <Users size={32} color="var(--primary)" style={{ marginBottom: 8 }} />
                        <h3>12</h3>
                        <p className="text-sm">{isRtl ? 'إجمالي المرضى' : 'Total Patients'}</p>
                    </div>
                    <div className="glass-card flex flex-col items-center justify-center text-center p-md" style={{ padding: 16 }}>
                        <AlertTriangle size={32} color="var(--danger)" style={{ marginBottom: 8 }} />
                        <h3>2</h3>
                        <p className="text-sm">{isRtl ? 'حالات حرجة' : 'Critical Alerts'}</p>
                    </div>
                </div>

                <div>
                    <div className="flex justify-between items-center" style={{ marginBottom: 12 }}>
                        <h3>{isRtl ? 'المواعيد القادمة' : 'Upcoming Appointments'}</h3>
                    </div>
                    <div className="glass-card" style={{ padding: 16, borderLeft: '4px solid var(--secondary)' }}>
                        <p className="font-bold">Ahmed Ali - {isRtl ? 'متابعة سكر' : 'Glucose Follow-up'}</p>
                        <p className="text-sm">Today, 14:30 PM</p>
                    </div>
                </div>
            </div>
        );
    }

    // CAREGIVER DASHBOARD
    if (role === 'caregiver') {
        return (
            <div className="flex flex-col gap-lg">
                <div className="glass-panel" style={{ padding: 20 }}>
                    <div className="flex justify-between items-center">
                        <div>
                            <h2 style={{ margin: 0, fontSize: '1.2rem' }}>{isRtl ? 'مراقبة: أحمد علي' : 'Monitoring: Ahmed Ali'}</h2>
                            <p className="text-sm">{isRtl ? 'الحالة مستقرة' : 'Condition Stable'}</p>
                        </div>
                        <CheckCircle color="var(--success)" size={28} />
                    </div>
                    {/* Device Status Header (Signal & Battery) */}
                    {synced && (
                        <div className="flex justify-between items-center" style={{ marginTop: 16, background: 'var(--glass-border)', padding: '8px 12px', borderRadius: 12 }}>
                            <div className="flex items-center gap-sm">
                                <div className="flex items-end gap-[2px]" style={{ height: 14 }}>
                                    {[1, 2, 3, 4].map(bar => (
                                        <div key={bar} style={{
                                            width: 3,
                                            height: bar * 3,
                                            background: rssi && (rssi > -90 + (bar * 10)) ? 'var(--primary)' : 'var(--text-muted)',
                                            opacity: rssi && (rssi > -90 + (bar * 10)) ? 1 : 0.3,
                                            borderRadius: 1
                                        }} />
                                    ))}
                                </div>
                                <span style={{ fontSize: '0.7rem', fontWeight: 700, opacity: 0.8 }}>{isRtl ? 'الإشارة' : 'Signal'}</span>
                            </div>

                            {battery !== null && (
                                <div className="flex items-center gap-sm">
                                    <span style={{ fontSize: '0.75rem', fontWeight: 800, color: battery < 20 ? 'var(--danger)' : 'var(--text-main)' }}>{battery}%</span>
                                    <div style={{ width: 22, height: 12, border: '1.5px solid currentColor', borderRadius: 2, position: 'relative', padding: 1, color: battery < 20 ? 'var(--danger)' : 'var(--text-main)' }}>
                                        <div style={{ width: `${battery}%`, height: '100%', background: battery < 20 ? 'var(--danger)' : 'var(--primary)', borderRadius: 1 }} />
                                        <div style={{ position: 'absolute', right: -3, top: 2, width: 2, height: 4, background: 'currentColor', borderRadius: '0 1px 1px 0' }} />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>


                <div className="flex justify-between items-center">
                    <h3>{isRtl ? 'المؤشرات الحالية' : 'Live Vitals'}</h3>
                    <button className="btn-primary" onClick={() => setSynced(!synced)} style={{ padding: '8px 16px', fontSize: '0.85rem' }}>
                        {synced ? (isRtl ? 'إيقاف المزامنة' : 'Stop Sync') : (isRtl ? 'تحديث حي' : 'Live Sync')}
                    </button>
                </div>

                <div className="grid grid-cols-2">
                    {Object.entries(vitals).map(([key, vital]) => (
                        <motion.div
                            key={key}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => navigate(`/vitals/${key}`)}
                            className="glass-card"
                            style={{ padding: 16, borderTop: `4px solid ${vital.color}`, cursor: 'pointer' }}
                        >
                            <div className="flex gap-sm items-center" style={{ marginBottom: 12 }}>
                                <vital.icon color={vital.color} size={20} />
                                <h3 style={{ margin: 0, fontSize: '0.9rem' }}>{vital.label}</h3>
                            </div>
                            <div className="flex items-baseline gap-sm">
                                <span style={{ fontSize: '1.8rem', fontWeight: 800, color: vital.color }}>
                                    {vital.value}
                                </span>
                                <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                                    {vital.unit}
                                </span>
                            </div>
                        </motion.div>
                    ))}
                </div>
            </div>
        );
    }

    // PATIENT DASHBOARD (DEFAULT)
    return (
        <div className="flex flex-col gap-lg">
            <div className="glass-panel" style={{ padding: '22px 22px 20px', background: 'linear-gradient(135deg,rgba(16,185,129,0.18) 0%,rgba(52,211,153,0.06) 100%)' }}>
                <h2 style={{ margin: 0, marginBottom: 4 }}>{isRtl ? 'لوحة تحكم أحمد' : 'Ahmed\'s Dashboard'}</h2>
                <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: 'rgba(239, 68, 68, 0.1)', color: 'var(--danger)', padding: '4px 12px', borderRadius: 20, fontSize: '0.8rem', fontWeight: 700, marginBottom: 16 }}>
                    <span style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--danger)' }} />
                    {isRtl ? 'مريض سكري وضغط دم' : 'Diabetes & Hypertension Patient'}
                </div>
                <p className="text-sm" style={{ marginBottom: 16 }}>
                    {isRtl ? 'مراقبة حية عبر الساعة الذكية.' : 'Real-time health monitoring via smartwatch.'}
                </p>
                {/* Device Status Header (Signal & Battery) */}
                {synced && (
                    <div className="flex justify-between items-center" style={{ marginBottom: 16, background: 'rgba(255,255,255,0.05)', padding: '8px 12px', borderRadius: 12 }}>
                        <div className="flex items-center gap-sm">
                            <div className="flex items-end gap-[2px]" style={{ height: 14 }}>
                                {[1, 2, 3, 4].map(bar => (
                                    <div key={bar} style={{
                                        width: 3,
                                        height: bar * 3,
                                        background: rssi && (rssi > -90 + (bar * 10)) ? 'var(--primary)' : 'rgba(255,255,255,0.2)',
                                        borderRadius: 1
                                    }} />
                                ))}
                            </div>
                            <span style={{ fontSize: '0.7rem', fontWeight: 700, opacity: 0.8 }}>{isRtl ? 'الإشارة' : 'Signal'}</span>
                        </div>

                        {battery !== null && (
                            <div className="flex items-center gap-sm">
                                <span style={{ fontSize: '0.75rem', fontWeight: 800, color: battery < 20 ? 'var(--danger)' : 'inherit' }}>{battery}%</span>
                                <div style={{ width: 22, height: 12, border: '1.5px solid currentColor', borderRadius: 2, position: 'relative', padding: 1 }}>
                                    <div style={{ width: `${battery}%`, height: '100%', background: battery < 20 ? 'var(--danger)' : 'var(--primary)', borderRadius: 1 }} />
                                    <div style={{ position: 'absolute', right: -3, top: 2, width: 2, height: 4, background: 'currentColor', borderRadius: '0 1px 1px 0' }} />
                                </div>
                            </div>
                        )}
                    </div>
                )}

                <button
                    className="btn-primary flex justify-center items-center gap-sm"
                    onClick={synced ? handleDisconnect : startScanner}

                    style={{
                        width: '100%', borderRadius: 16,
                        background: synced
                            ? 'linear-gradient(135deg,#dc2626,#ef4444)'
                            : 'linear-gradient(135deg,#059669,#10b981)',
                        boxShadow: synced ? '0 6px 20px rgba(239,68,68,0.35)' : '0 6px 20px rgba(16,185,129,0.35)'
                    }}
                >
                    <Watch size={20} className={synced && bluetoothActive ? 'animate-pulse' : ''} />
                    {synced ? (isRtl ? 'فصل الجهاز' : 'Disconnect Device') : (isRtl ? 'ربط الجهاز Life Care' : 'Connect Life Care Device')}
                </button>

                {/* Connection mode badge */}
                {synced && connMode && (
                    <div className="flex justify-center" style={{ marginTop: 10 }}>
                        <span style={{
                            fontSize: '0.72rem', fontWeight: 700, padding: '4px 12px', borderRadius: 20,
                            background: connMode === 'ws' ? 'rgba(59,130,246,0.15)' : 'rgba(16,185,129,0.15)',
                            color: connMode === 'ws' ? 'var(--secondary)' : 'var(--primary)',
                            border: `1px solid ${connMode === 'ws' ? 'rgba(59,130,246,0.3)' : 'rgba(16,185,129,0.3)'}`,
                            display: 'flex', alignItems: 'center', gap: 6
                        }}>
                            <span style={{ width: 7, height: 7, borderRadius: '50%', background: connMode === 'ws' ? 'var(--secondary)' : 'var(--primary)', display: 'inline-block' }} className="animate-pulse" />
