                                ? (isRtl ? 'متصل عبر Bridge' : 'Connected via WS Bridge')
                                : (isRtl ? 'متصل عبر BLE مباشر' : 'Connected via BLE Direct')}
                        </span>
                    </div>
                )}
            </div>

            {/* ── Connecting Overlay ─────────────────────────────────── */}
            <AnimatePresence>
                {connecting && (
                    <motion.div
                        key="conn-overlay"
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        style={{
                            position: 'fixed', inset: 0, zIndex: 1000,
                            background: 'rgba(0,0,0,0.65)', backdropFilter: 'blur(8px)',
                            display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 24
                        }}
                    >
                        {/* Icon area */}
                        {connStatus !== 'error' ? (
                            <div style={{ position: 'relative', width: 100, height: 100, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                <motion.div
                                    animate={{ scale: [1, 1.25, 1], opacity: [0.4, 0.15, 0.4] }}
                                    transition={{ repeat: Infinity, duration: 1.6 }}
                                    style={{ position: 'absolute', inset: -18, borderRadius: '50%', background: connStatus === 'connected' ? 'var(--success)' : 'var(--primary)' }}
                                />
                                <motion.div
                                    animate={{ scale: [1, 1.12, 1], opacity: [0.3, 0.1, 0.3] }}
                                    transition={{ repeat: Infinity, duration: 1.6, delay: 0.3 }}
                                    style={{ position: 'absolute', inset: -6, borderRadius: '50%', background: connStatus === 'connected' ? 'var(--success)' : 'var(--primary)' }}
                                />
                                <div style={{
                                    width: 80, height: 80, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    background: connStatus === 'connected' ? 'var(--success)' : 'linear-gradient(135deg,#059669,#10b981)',
                                    boxShadow: `0 12px 40px ${connStatus === 'connected' ? 'rgba(16,185,129,0.5)' : 'rgba(16,185,129,0.4)'}`
                                }}>
                                    {connStatus === 'connected'
                                        ? <CheckCircle color="white" size={40} />
                                        : <Watch color="white" size={36} className="animate-pulse" />}
                                </div>
                            </div>
                        ) : (
                            <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'rgba(239,68,68,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                <AlertTriangle color="var(--danger)" size={38} />
                            </div>
                        )}

                        {/* Status text */}
                        <div style={{ textAlign: 'center', color: 'white' }}>
                            <h2 style={{ color: 'white', marginBottom: 8 }}>
                                {connStatus === 'scanning' && (isRtl ? 'جارٍ البحث عن الجهاز...' : 'Scanning for device...')}
                                {connStatus === 'connecting' && (isRtl ? 'جارٍ الاتصال بـ Life Care...' : 'Connecting to Life Care...')}
                                {connStatus === 'connected' && (isRtl ? 'تم الاتصال بنجاح!' : 'Connected!')}
                                {connStatus === 'error' && (isRtl ? 'فشل الاتصال' : 'Connection Failed')}
                            </h2>
                            <p style={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.9rem' }}>
                                {connStatus === 'scanning' && (isRtl ? 'جهاز Life Care (ESP32-C3)' : 'Life Care device (ESP32-C3)')}
                                {connStatus === 'connecting' && (isRtl ? 'اشتراك في قراءات الحيوية...' : 'Subscribing to vitals...')}
                                {connStatus === 'connected' && (isRtl ? 'البيانات تصل الآن' : 'Live data incoming')}
                                {connStatus === 'error' && connError}
                            </p>
                        </div>

                        {/* Cancel / Retry */}
                        {connStatus === 'error' ? (
                            <div className="flex gap-md">
                                <button
                                    onClick={() => { setConnecting(false); setConnError(''); }}
                                    style={{ background: 'rgba(255,255,255,0.15)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: 14, padding: '10px 24px', cursor: 'pointer', fontWeight: 600 }}
                                >
                                    {isRtl ? 'إغلاق' : 'Close'}
                                </button>
                                <button
                                    onClick={() => { setConnecting(false); setTimeout(startScanner, 100); }}
                                    className="btn-primary"
                                    style={{ borderRadius: 14, padding: '10px 24px' }}
                                >
                                    {isRtl ? 'إعادة المحاولة' : 'Retry'}
                                </button>
                            </div>
                        ) : connStatus !== 'connected' ? (
                            <button
                                onClick={() => { setConnecting(false); if (wsRef.current) wsRef.current.close(); }}
                                style={{ background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.25)', color: 'white', borderRadius: 14, padding: '10px 28px', cursor: 'pointer', fontWeight: 600 }}
                            >
                                {isRtl ? 'إلغاء' : 'Cancel'}
                            </button>
                        ) : null}
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Emergency Alert Overlay */}
            <AnimatePresence>
                {isAlerting && (
                    <motion.div
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        style={{ position: 'fixed', inset: 0, background: 'rgba(220,38,38,0.92)', zIndex: 9999, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'white', backdropFilter: 'blur(10px)' }}
                    >
                        <motion.div
                            animate={{ scale: [1, 1.2, 1] }} transition={{ repeat: Infinity, duration: 1 }}
                            style={{ background: 'white', padding: 20, borderRadius: '50%', marginBottom: 20 }}
                        >
                            <AlertTriangle size={60} color="#dc2626" />
                        </motion.div>
                        <h1 style={{ color: 'white', fontSize: '2rem', textAlign: 'center', padding: '0 20px' }}>{alertMsg}</h1>
                        <p style={{ color: 'rgba(255,255,255,0.9)', marginBottom: 32 }}>{isRtl ? 'يرجى مراجعة الطبيب فوراً!' : 'Please check vitals or seek help!'}</p>
                        <button
                            onClick={() => setIsAlerting(false)}
                            style={{ background: 'white', color: '#dc2626', border: 'none', padding: '12px 40px', borderRadius: 16, fontWeight: 800, cursor: 'pointer' }}
                        >
                            {isRtl ? 'كتم التنبيه' : 'Mute Alert'}
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Scanning Modal */}
            <AnimatePresence>
                {showScanner && (
                    <>
                        <motion.div
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100dvh', background: 'rgba(0,0,0,0.5)', zIndex: 999, backdropFilter: 'blur(4px)' }}
                            onClick={() => setShowScanner(false)}
                        />
                        <motion.div
                            initial={{ opacity: 0, y: 100, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 100 }}
                            className="glass-panel"
                            style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', width: '92%', maxWidth: 360, zIndex: 1000, padding: 24, display: 'flex', flexDirection: 'column', gap: 16 }}
                        >
                            <div className="flex justify-between items-center">
                                <h3 style={{ margin: 0 }}>
                                    {isRtl ? 'الأجهزة المتاحة' : 'BLE Devices'}
                                </h3>
                                <button onClick={() => setShowScanner(false)} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}>✕</button>
                            </div>

                            {scanningStep === 'searching' && (
                                <div className="flex flex-col items-center" style={{ margin: '16px 0', gap: 16 }}>
                                    <div style={{ position: 'relative', width: 80, height: 80, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                        <div className="animate-pulse" style={{ position: 'absolute', inset: -12, background: 'var(--primary)', opacity: 0.15, borderRadius: '50%' }} />
                                        <div className="animate-pulse" style={{ position: 'absolute', inset: -4, background: 'var(--primary)', opacity: 0.1, borderRadius: '50%' }} />
                                        <div style={{ background: 'var(--primary)', padding: 18, borderRadius: '50%', color: 'white' }}>
                                            <Watch size={36} />
                                        </div>
                                    </div>
                                    <p className="text-sm" style={{ textAlign: 'center', color: 'var(--text-muted)' }}>
                                        {isRtl ? 'جارٍ البحث عن جهاز Life Care...' : 'Scanning for Life Care device...'}
                                    </p>
                                </div>
                            )}

                            {scanningStep === 'found' && (
                                <div className="flex flex-col gap-sm">
                                    <p className="text-sm" style={{ textAlign: 'center', color: 'var(--text-muted)', marginBottom: 4 }}>
                                        {isRtl ? 'اختر طريقة الاتصال:' : 'Choose connection method:'}
                                    </p>

                                    {/* ── Real ESP32 Device ── */}
                                    {navigator.bluetooth && (
                                        <button
                                            className="glass-card flex items-center gap-md"
                                            onClick={connectNativeBluetooth}
                                            style={{ padding: '14px 16px', cursor: 'pointer', border: '2px solid var(--primary)', textAlign: 'start', width: '100%' }}
                                        >
                                            <div style={{ background: 'linear-gradient(135deg,#059669,#10b981)', color: 'white', padding: 10, borderRadius: 12, flexShrink: 0 }}>
                                                <Watch size={22} />
                                            </div>
                                            <div className="flex flex-col" style={{ gap: 2 }}>
                                                <span className="font-bold" style={{ color: 'var(--primary)', fontSize: '0.95rem' }}>
                                                    Life Care {isRtl ? '(ESP32-C3)' : '(ESP32-C3)'}
                                                </span>
                                                <span className="text-sm" style={{ color: 'var(--text-muted)' }}>
                                                    {isRtl ? 'BLE حقيقي • خدمة 0x180D • HR + Temp + SpO₂' : 'Real BLE • Service 0x180D • HR + Temp + SpO₂'}
                                                </span>
                                            </div>
                                            <span style={{ marginInlineStart: 'auto', fontSize: '0.7rem', background: 'rgba(16,185,129,0.15)', color: 'var(--primary)', padding: '3px 8px', borderRadius: 8, fontWeight: 700, flexShrink: 0 }}>
                                                LIVE
                                            </span>
                                        </button>
                                    )}

                                    {/* ── Demo / Simulated fallback ── */}
                                    <button
                                        className="glass-card flex items-center gap-md"
                                        onClick={connectSimulatedWatch}
                                        style={{ padding: '14px 16px', cursor: 'pointer', textAlign: 'start', width: '100%' }}
                                    >
                                        <div style={{ background: 'linear-gradient(135deg,#2563eb,#3b82f6)', color: 'white', padding: 10, borderRadius: 12, flexShrink: 0 }}>
                                            <Activity size={22} />
                                        </div>
                                        <div className="flex flex-col" style={{ gap: 2 }}>
                                            <span className="font-bold" style={{ fontSize: '0.95rem' }}>{isRtl ? 'جهاز تجريبي (محاكاة)' : 'Demo Device (Simulated)'}</span>
                                            <span className="text-sm" style={{ color: 'var(--text-muted)' }}>{isRtl ? 'بيانات وهمية للاختبار' : 'Mock data — no real device needed'}</span>
                                        </div>
                                        <span style={{ marginInlineStart: 'auto', fontSize: '0.7rem', background: 'rgba(59,130,246,0.12)', color: 'var(--secondary)', padding: '3px 8px', borderRadius: 8, fontWeight: 700, flexShrink: 0 }}>
                                            DEMO
                                        </span>
                                    </button>
                                </div>
                            )}

                            {scanningStep === 'error' && (
                                <div className="flex flex-col items-center text-center" style={{ gap: 12, padding: '12px 0' }}>
                                    <AlertTriangle size={40} color="var(--danger)" />
                                    <p style={{ color: 'var(--danger)', fontWeight: 600 }}>
                                        {isRtl ? 'تعذّر الاتصال بالجهاز' : 'Connection failed'}
                                    </p>
                                    <button className="btn-primary" style={{ padding: '10px 24px' }} onClick={() => { setScanningStep('found'); }}>
                                        {isRtl ? 'إعادة المحاولة' : 'Retry'}
                                    </button>
                                </div>
                            )}

                            <button
                                className="btn-secondary"
                                style={{ background: 'transparent', color: 'var(--text-muted)', border: '1px solid var(--glass-border)', boxShadow: 'none', padding: '10px' }}
                                onClick={() => setShowScanner(false)}
                            >
                                {isRtl ? 'إلغاء' : 'Cancel'}
                            </button>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>

            <div className="flex justify-between items-center">
                <h3>{isRtl ? 'المؤشرات الحيوية' : 'Your Vitals'}</h3>
            </div>

            <div className="grid grid-cols-2">
                {Object.entries(vitals).map(([key, vital]) => (
                    <motion.div
                        key={key}
                        whileTap={{ scale: 0.95 }}
                        onClick={() => navigate(`/vitals/${key}`)}
                        className="glass-card text-center"
                        style={{ padding: '20px 12px', borderBottom: `4px solid ${vital.color}`, cursor: 'pointer' }}
                    >
                        <div className="flex justify-center" style={{ marginBottom: 12 }}>
                            <div style={{
                                background: `${vital.color}20`,
                                padding: 12,
                                borderRadius: '50%',
                                position: 'relative'
                            }}>
                                {vital.lastSync && (
                                    <motion.div
                                        initial={{ scale: 0.8, opacity: 0.5 }}
                                        animate={{ scale: 1.5, opacity: 0 }}
                                        key={vital.lastSync}
                                        style={{ position: 'absolute', inset: 0, background: vital.color, borderRadius: '50%', zIndex: -1 }}
                                    />
                                )}
                                <vital.icon color={vital.color} size={24} />
                            </div>
                        </div>

                        <h3 style={{ fontSize: '0.9rem', marginBottom: 4 }}>{vital.label}</h3>
                        <div className="flex justify-center items-baseline gap-sm">
                            <span style={{ fontSize: '1.5rem', fontWeight: 700, color: vital.color }}>
                                {vital.value}
                            </span>
                            <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                                {vital.unit}
                            </span>
                        </div>
                        {vital.lastSync && (
                            <div className="flex justify-center mt-2">
                                <span className="animate-pulse" style={{ fontSize: '0.6rem', color: 'var(--primary)', background: 'rgba(16,185,129,0.1)', padding: '2px 6px', borderRadius: 6, fontWeight: 700 }}>
                                    ● LIVE
                                </span>
                            </div>
                        )}
                    </motion.div>
                ))}
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User, PhoneCall, Video, CalendarCheck, Share2, Search, XCircle, CheckCircle, Clock } from 'lucide-react';

export default function Doctors() {
    const lang = document.documentElement.lang || 'ar';
    const isRtl = lang === 'ar';

    // Mock data initially, will update with real fetch if possible
    const [doctors, setDoctors] = useState([
        { id: 'd1', name: 'Dr. Sarah Ahmed', special: 'Cardiologist', status: 'approved' },
        { id: 'd2', name: 'Dr. John Smith', special: 'General Physician', status: 'pending' }
    ]);

    const [doctorIdInput, setDoctorIdInput] = useState('');
    const [isSearching, setIsSearching] = useState(false);
    const [searchMessage, setSearchMessage] = useState('');
    const [verifiedDoctor, setVerifiedDoctor] = useState(null);

    const [allDoctors, setAllDoctors] = useState([]);
    const [doctorSearch, setDoctorSearch] = useState('');

    const token = localStorage.getItem('token') || ''; // JWT token if exists

    // Example of how we fetch connected doctors
    useEffect(() => {
        if (!token) {
            // Mock available doctors
            setAllDoctors([
                { _id: 'doc1', name: 'Dr. Ahmed Ibrahim', specialty: 'Cardiologist', hospital: 'Life Care' },
                { _id: 'doc2', name: 'Dr. Mona Hassan', specialty: 'Neurology', hospital: 'Al Shifa' }
            ]);
            return;
        }

        // Fetch user's connected doctors
        fetch('http://localhost:5000/api/connections/get_patient_doctors', {
            headers: { 'Authorization': `Bearer ${token}` }
        })
            .then(res => res.json())
            .then(data => {
                if (data && data.data) {
                    const mapped = data.data.map(conn => ({
                        id: conn.doctor_id._id,
                        connId: conn._id,
                        name: conn.doctor_id.name,
                        special: conn.doctor_id.specialty || 'Specialist',
                        status: conn.status
                    }));
                    setDoctors(mapped);
                }
            }).catch(err => console.error(err));

        // Fetch all platform doctors
        fetch('http://localhost:5000/api/patient/doctors-list', {
            headers: { 'Authorization': `Bearer ${token}` }
        })
            .then(res => res.json())
            .then(data => {
                if (data && data.data) {
                    setAllDoctors(data.data);
                }
            }).catch(err => console.error(err));
    }, [token]);

    const verifyDoctorId = async () => {
        if (!doctorIdInput.trim()) return;
        setIsSearching(true);
        setSearchMessage('');
        setVerifiedDoctor(null);

        try {
            const res = await fetch(`http://localhost:5000/api/connections/verify_doctor/${doctorIdInput}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const data = await res.json();
            setIsSearching(false);

            if (res.ok && data.doctor) {
                setVerifiedDoctor(data.doctor);
                setSearchMessage(isRtl ? 'تم العثور على الطبيب بنجاح' : 'Doctor found successfully');
            } else {
                setSearchMessage(data.error || (isRtl ? 'لم يتم العثور على طبيب بهذا المعرف.' : 'Doctor not found with this ID.'));
            }
        } catch (error) {
            setIsSearching(false);
            setSearchMessage(isRtl ? 'تعذر الاتصال بالخادم.' : 'Could not connect to server.');
        }
    };

    const sendFollowRequest = async (targetId) => {
        // Support direct parameter or state input
        const idToUse = typeof targetId === 'string' ? targetId : doctorIdInput;
        if (!idToUse.trim()) return;

        setIsSearching(true);
        setSearchMessage('');

        try {
            const res = await fetch('http://localhost:5000/api/connections/send_follow_request', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ doctor_id: idToUse })
            });

            const data = await res.json();
            setIsSearching(false);

            if (res.ok) {
                setSearchMessage(isRtl ? 'تم إرسال الطلب بنجاح!' : 'Request sent successfully!');

                // Find doctor name if from list or verified
                const docInfo = allDoctors.find(d => d._id === idToUse) || verifiedDoctor;
                const docName = docInfo ? docInfo.name : 'Doctor (Pending)';
                const special = docInfo ? (docInfo.specialty || 'Unknown') : 'Unknown';

                setDoctors(prev => [{ id: idToUse, name: docName, special: special, status: 'pending' }, ...prev]);

                if (typeof targetId !== 'string') setDoctorIdInput('');
                setVerifiedDoctor(null); // Reset after success
            } else {
                setSearchMessage(data.error || (isRtl ? 'خطأ في الإرسال' : 'Error sending request'));
                if (typeof targetId === 'string') alert(data.error || (isRtl ? 'خطأ في الإرسال' : 'Error sending request'));
            }
        } catch (error) {
            setIsSearching(false);
            setSearchMessage(isRtl ? 'تعذر الاتصال بالخادم.' : 'Could not connect to server.');
            if (typeof targetId === 'string') alert(isRtl ? 'تعذر الاتصال بالخادم.' : 'Could not connect to server.');
        }
    };

    const endFollowUp = async (doc) => {
        if (!window.confirm(isRtl ? 'هل أنت متأكد من إنهاء المتابعة مع هذا الطبيب؟ سحب الصلاحيات فوري.' : 'Are you sure you want to end follow-up with this doctor?')) return;

        try {
            if (!token) {
                // Mock behavior if no token
                setDoctors(prev => prev.filter(d => d.id !== doc.id));
                return;
            }

            const res = await fetch(`http://localhost:5000/api/connections/end_follow_up/${doc.connId}`, {
                method: 'PUT',
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (res.ok) {
                setDoctors(prev => prev.filter(d => d.id !== doc.id));
            }
        } catch (error) {
            console.error(error);
        }
    };

    return (
        <div className="flex flex-col gap-lg pb-10">
            <div className="flex flex-col gap-sm mt-2">
                <div className="flex justify-between items-center">
                    <h2 style={{ fontSize: '1.4rem', margin: 0 }}>{isRtl ? 'طاقمك الطبي' : 'Your Care Team'}</h2>
                </div>
                <p className="text-sm text-muted">{isRtl ? 'إدارة الأطباء المتابعين لحالتك وإرسال طلبات جديدة.' : 'Manage your connected doctors and send new follow-up requests.'}</p>
            </div>

            {/* BROWSE ALL DOCTORS SECTION */}
            <div className="glass-card flex flex-col gap-md" style={{ padding: 20, borderTop: '4px solid var(--accent)', marginTop: 10 }}>
                <h3 style={{ margin: 0, fontSize: '1.1rem' }}>{isRtl ? 'تصفح قائمة الأطباء' : 'Browse All Doctors'}</h3>
                <p className="text-sm text-muted mb-2">{isRtl ? 'ابحث عن طبيب بالاسم أو التخصص لإضافته لطاقمك الطبي.' : 'Search for a doctor by name or specialty to add them to your care team.'}</p>
                <div style={{ position: 'relative' }}>
                    <input
                        type="text"
                        placeholder={isRtl ? 'البحث بالاسم أو التخصص...' : 'Search by name or specialty...'}
                        value={doctorSearch}
                        onChange={(e) => setDoctorSearch(e.target.value)}
                        style={{ padding: '12px 16px', paddingLeft: isRtl ? 16 : 40, paddingRight: isRtl ? 40 : 16, borderRadius: 12, border: '1px solid var(--glass-border)', background: 'var(--glass-bg)', width: '100%', color: 'var(--text-main)' }}
                    />
                    <Search size={18} color="var(--text-muted)" style={{ position: 'absolute', right: isRtl ? 14 : 'auto', left: isRtl ? 'auto' : 14, top: 14 }} />
                </div>

                <div className="flex flex-col gap-sm mt-2" style={{ maxHeight: '250px', overflowY: 'auto', paddingRight: 4 }}>
                    {allDoctors.length === 0 && <p className="text-sm text-muted">{isRtl ? 'لا يوجد أطباء متاحين حالياً.' : 'No doctors available currently.'}</p>}
                    {allDoctors.filter(d =>
                        (d.name && d.name.toLowerCase().includes(doctorSearch.toLowerCase())) ||
                        (d.specialty && d.specialty.toLowerCase().includes(doctorSearch.toLowerCase()))
                    ).map(doc => {
                        const isConnected = doctors.some(connected => connected.id === doc._id);
                        return (
                            <div key={doc._id} className="flex justify-between items-center" style={{ padding: '12px', background: 'var(--bg-main)', borderRadius: 12, border: '1px solid var(--glass-border)' }}>
                                <div className="flex items-center gap-md">
                                    <div style={{ padding: 8, background: 'var(--primary)', color: 'white', borderRadius: '50%' }}>
                                        <User size={18} />
                                    </div>
                                    <div className="flex flex-col">
                                        <span style={{ fontWeight: 600, fontSize: '0.95rem' }}>{doc.name}</span>
                                        <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{doc.specialty || 'General'} • {doc.hospital || 'Clinic'}</span>
                                    </div>
                                </div>
                                <button
                                    onClick={() => sendFollowRequest(doc._id)}
                                    disabled={isConnected || isSearching}
                                    style={{
                                        padding: '6px 12px', borderRadius: 8, border: 'none', cursor: isConnected ? 'not-allowed' : 'pointer', fontWeight: 'bold', fontSize: '0.8rem',
                                        background: isConnected ? 'var(--glass-border)' : 'var(--primary)', color: isConnected ? 'var(--text-muted)' : 'white'
                                    }}
                                >
                                    {isConnected ? (isRtl ? 'مضاف' : 'Added') : (isRtl ? 'إضافة' : 'Add')}
                                </button>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* SEND REQUEST TO DOCTOR BY ID (Manual) */}
            <div className="glass-card flex flex-col gap-md" style={{ padding: 20, borderTop: '4px solid var(--primary)' }}>
                <h3 style={{ margin: 0, fontSize: '1.1rem' }}>{isRtl ? 'إضافة بمعرف الطبيب (Doctor ID)' : 'Add by Doctor ID'}</h3>
                <p className="text-sm text-muted mb-2">{isRtl ? 'أدخل معرف الدكتور (Doctor ID) للتحقق منه وبدء المتابعة.' : 'Enter Doctor ID to verify and start follow-up.'}</p>
                <div className="flex gap-sm">
                    <div style={{ position: 'relative', flex: 1 }}>
                        <input
                            type="text"
                            placeholder={isRtl ? 'مثال: DOC12345...' : 'Example: DOC12345...'}
                            value={doctorIdInput}
                            onChange={(e) => { setDoctorIdInput(e.target.value.toUpperCase()); setVerifiedDoctor(null); }}
                            style={{ padding: '12px 16px', borderRadius: 12, border: '1px solid var(--glass-border)', background: 'var(--glass-bg)', width: '100%', color: 'var(--text-main)', textTransform: 'uppercase' }}
                        />
                    </div>
                    <button onClick={verifyDoctorId} disabled={isSearching || !doctorIdInput} className="btn-secondary flex items-center gap-sm" style={{ padding: '0 20px', borderRadius: 12 }}>
                        {isSearching ? '...' : <Search size={18} />} {isRtl ? 'بحث' : 'Search'}
                    </button>
                </div>
                {searchMessage && !verifiedDoctor && <div style={{ fontSize: '0.85rem', color: searchMessage.includes('نجاح') || searchMessage.includes('successfully') ? 'var(--success)' : 'var(--danger)', fontWeight: 600 }}>{searchMessage}</div>}

                {/* Verified Doctor Card */}
                {verifiedDoctor && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}
                        className="flex flex-col gap-sm" style={{ marginTop: 10, padding: 16, background: 'var(--bg-main)', borderRadius: 12, border: '1px solid var(--success)' }}
                    >
                        <div className="flex items-center gap-md">
                            <div style={{ width: 48, height: 48, borderRadius: '50%', background: 'var(--success)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}>
                                <User size={24} />
                            </div>
                            <div className="flex flex-col flex-1">
                                <span style={{ fontWeight: 'bold', fontSize: '1.05rem', color: 'var(--text-main)' }}>{verifiedDoctor.name}</span>
                                <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{verifiedDoctor.specialty} • {verifiedDoctor.hospital}</span>
                            </div>
                        </div>
                        <button
                            onClick={() => sendFollowRequest(verifiedDoctor._id)}
                            disabled={isSearching}
                            className="btn-primary mt-2 flex items-center justify-center gap-sm" style={{ width: '100%', padding: '10px', background: 'var(--success)' }}
                        >
                            <CheckCircle size={18} /> {isRtl ? 'بدء المتابعة' : 'Start Follow-up'}
                        </button>
                    </motion.div>
                )}
            </div>

            <div className="flex flex-col gap-md mt-2">
                <h3 style={{ margin: 0, fontSize: '1.2rem' }}>{isRtl ? 'الأطباء المرتبطين بملفك' : 'Connected Doctors'}</h3>
                {doctors.length === 0 && <p className="text-sm text-muted">{isRtl ? 'لا يوجد أطباء متابعين لحالتك حتى الآن.' : 'No doctors following your case yet.'}</p>}

                {doctors.map(doc => (
                    <motion.div
                        key={doc.id}
                        whileHover={{ scale: 1.01 }}
                        className="glass-card flex flex-col justify-between"
                        style={{ padding: 20, borderLeft: doc.status === 'approved' ? '4px solid var(--success)' : '4px solid var(--warning)' }}
                    >
                        <div className="flex items-start gap-md mb-4 justify-between">
                            <div className="flex items-center gap-md">
                                <div
                                    className="flex items-center justify-center font-bold"
                                    style={{ width: 50, height: 50, borderRadius: '50%', background: 'var(--primary)', color: 'white', fontSize: '1.2rem' }}
                                >
                                    <User size={24} />
                                </div>
                                <div>
                                    <h2 style={{ margin: 0, fontSize: '1.1rem' }}>{doc.name}</h2>
                                    <span className="text-muted text-sm flex gap-sm items-center">
                                        {doc.status === 'pending' ? <Clock size={14} color="var(--warning)" /> : <CheckCircle size={14} color="var(--success)" />}
                                        {doc.status === 'pending' ? (isRtl ? 'قيد الانتظار لمعالجة الطلب...' : 'Pending doctor approval...') : doc.special}
                                    </span>
                                </div>
                            </div>

                            {doc.status === 'approved' && (
                                <button onClick={() => endFollowUp(doc)} className="btn-secondary flex items-center gap-sm" style={{ padding: '6px 12px', fontSize: '0.8rem', color: 'var(--danger)', borderColor: 'var(--danger)' }}>
                                    <XCircle size={16} /> {isRtl ? 'إنهاء المتابعة' : 'End Follow-up'}
                                </button>
                            )}
                        </div>

                        {doc.status === 'approved' && (
                            <div className="flex gap-sm">
                                <button className="flex-1 flex items-center justify-center gap-sm glass-card text-success" style={{ padding: '10px', border: 'none', cursor: 'pointer', background: 'rgba(16, 185, 129, 0.1)' }}>
                                    <PhoneCall size={18} /> {isRtl ? 'اتصال' : 'Call'}
                                </button>
                                <button className="flex-1 flex items-center justify-center gap-sm btn-primary" style={{ padding: '10px' }}>
                                    <CalendarCheck size={18} /> {isRtl ? 'موعد' : 'Book'}
                                </button>
                            </div>
                        )}
                    </motion.div>
                ))}
            </div>
        </div>
    );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Mail, AlertCircle, CheckCircle, ArrowRight, ArrowLeft } from 'lucide-react';

export default function ForgotPassword({ lang, toggleLang, theme, toggleTheme }) {
    const navigate = useNavigate();
    const isRtl = lang === 'ar';
    const [email, setEmail] = useState('');
    const [status, setStatus] = useState('idle'); // idle, loading, success, error
    const [message, setMessage] = useState('');

    const t = {
        ar: {
            title: "إعادة تعيين كلمة المرور",
            subtitle: "أدخل بريدك الإلكتروني وسنرسل لك رابطاً للتعيين",
            email: "البريد الإلكتروني",
            send: "إرسال رابط التعيين",
            loading: "جاري الإرسال...",
            back: "العودة لتسجيل الدخول",
            errEmail: "يرجى إدخال بريد إلكتروني صحيح"
        },
        en: {
            title: "Reset Password",
            subtitle: "Enter your email and we'll send you a reset link",
            email: "Email Address",
            send: "Send Reset Link",
            loading: "Sending...",
            back: "Back to Login",
            errEmail: "Please enter a valid email address"
        }
    }[lang];

    const handleSubmit = async (e) => {
        e.preventDefault();

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email.trim())) {
            setStatus('error');
            setMessage(t.errEmail);
            return;
        }

        setStatus('loading');
        try {
            const res = await fetch('http://localhost:5000/api/auth/forgot-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email })
            });
            const data = await res.json();

            if (res.ok) {
                setStatus('success');
                setMessage(data.message);
            } else {
                setStatus('error');
                setMessage(data.error || 'Failed to send rest link');
            }
        } catch (err) {
            setStatus('error');
            setMessage('Server error. Please try again later.');
        }
    };

    return (
        <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', position: 'relative', padding: 24 }}>
            {/* Top controls */}
            <div className="flex justify-start items-center" style={{ paddingTop: 'max(14px, env(safe-area-inset-top))', marginBottom: 32 }}>
                <button
                    onClick={toggleLang}
                    style={{ background: 'var(--glass-bg)', border: '1px solid var(--glass-border)', borderRadius: 20, padding: '6px 14px', cursor: 'pointer', fontSize: '0.82rem', fontWeight: 700, color: 'var(--text-main)', fontFamily: 'inherit' }}
                >
                    {isRtl ? 'English' : 'عربي'}
                </button>
            </div>

            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center' }}>
                <motion.div
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    className="flex flex-col"
                    style={{ gap: 16, width: '100%', maxWidth: 400 }}
                >
                    <div className="text-center" style={{ marginBottom: 16 }}>
                        <h2 style={{ fontSize: '1.6rem', margin: 0 }}>{t.title}</h2>
                        <p style={{ color: 'var(--text-sub)', marginTop: 8 }}>{t.subtitle}</p>
                    </div>

                    {status === 'error' && (
                        <div style={{ background: 'rgba(239, 68, 68, 0.1)', border: '1px solid var(--danger)', padding: 12, borderRadius: 12, display: 'flex', gap: 8, alignItems: 'center' }}>
                            <AlertCircle color="var(--danger)" size={20} flexShrink={0} />
                            <span style={{ color: 'var(--danger)', fontSize: '0.85rem', fontWeight: 600 }}>{message}</span>
                        </div>
                    )}

                    {status === 'success' ? (
                        <div style={{ background: 'rgba(16, 185, 129, 0.1)', border: '1px solid var(--primary)', padding: 16, borderRadius: 12, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, textAlign: 'center' }}>
                            <CheckCircle color="var(--primary)" size={48} />
                            <span style={{ color: 'var(--primary)', fontSize: '1rem', fontWeight: 600 }}>{message}</span>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="flex flex-col gap-md">
                            <div style={{ position: 'relative' }}>
                                <Mail size={18} color="var(--primary)" style={{ position: 'absolute', top: '50%', transform: 'translateY(-50%)', [isRtl ? 'right' : 'left']: 14, pointerEvents: 'none' }} />
                                <input
                                    type="email"
                                    placeholder={t.email}
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    style={{
                                        [isRtl ? 'paddingRight' : 'paddingLeft']: 40,
                                        paddingTop: 14,
                                        paddingBottom: 14,
                                        paddingLeft: isRtl ? 16 : 40,
                                        paddingRight: isRtl ? 40 : 16,
                                        border: '1px solid var(--glass-border)',
                                        background: 'var(--glass-bg)',
                                        width: '100%',
                                        borderRadius: 12
                                    }}
                                />
                            </div>

                            <button
                                type="submit"
                                className="btn-primary"
                                style={{ marginTop: 8, padding: 16, borderRadius: 18, opacity: status === 'loading' ? 0.7 : 1 }}
                                disabled={status === 'loading'}
                            >
                                {status === 'loading' ? t.loading : t.send}
                            </button>
                        </form>
                    )}

                    <button
                        onClick={() => navigate('/welcome')}
                        style={{
                            background: 'transparent', border: 'none', color: 'var(--text-muted)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
                            marginTop: 16, cursor: 'pointer', fontWeight: 600
                        }}
                    >
                        {isRtl ? <ArrowRight size={16} /> : <ArrowLeft size={16} />}
                        {t.back}
                    </button>
                </motion.div>
            </div>
        </div>
    );
}

import { useState, useEffect, useRef } from 'react';
import {
    Pill, Clock, CalendarDays, Plus, Bell, Image as ImageIcon,
    Type, X, AlertTriangle, CheckCircle2, Camera, BellRing, Trash2, BellOff
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const ALARM_SOUND = 'https://actions.google.com/sounds/v1/alarms/beep_short.ogg';

export default function Medications() {
    const lang = document.documentElement.lang || 'ar';
    const isRtl = lang === 'ar';

    const [meds, setMeds] = useState([
        {
            id: 1,
            name: 'Lisinopril',
            image: null,
            dose: '10mg',
            times: ['08:00', '20:00'],
            days: [0, 1, 2, 3, 4, 5, 6], // 0: Sunday, 1: Monday, etc.
            takenToday: false,
            color: 'var(--secondary)'
        }
    ]);

    const [showAddForm, setShowAddForm] = useState(false);
    const [activeAlarm, setActiveAlarm] = useState(null);

    // Form State
    const [newName, setNewName] = useState('');
    const [newImage, setNewImage] = useState(null);
    const [newDose, setNewDose] = useState('');
    const [newTime, setNewTime] = useState('');
    const [addedTimes, setAddedTimes] = useState([]);
    const [selectedDays, setSelectedDays] = useState([0, 1, 2, 3, 4, 5, 6]);

    const weekDays = isRtl
        ? ['أحد', 'إثنين', 'ثلاثاء', 'أربعاء', 'خميس', 'جمعة', 'سبت']
        : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    // Alarm Check Logic
    useEffect(() => {
        const checkAlarm = () => {
            const now = new Date();
            const currentDay = now.getDay();
            const currentHours = String(now.getHours()).padStart(2, '0');
            const currentMinutes = String(now.getMinutes()).padStart(2, '0');
            const currentTime = `${currentHours}:${currentMinutes}`;

            // We check every 5 seconds for demo, but normally every minute
            meds.forEach(med => {
                if (med.days.includes(currentDay) && med.times.includes(currentTime) && !med.takenToday) {
                    if (!activeAlarm || activeAlarm.id !== med.id) {
                        try {
                            const audio = new Audio(ALARM_SOUND);
                            audio.loop = true;
                            audio.play().catch(e => console.log('Audio play failed:', e));
                            setActiveAlarm({ ...med, audio });
                        } catch (err) {
                            setActiveAlarm(med);
                        }
                    }
                }
            });
        };

        const interval = setInterval(checkAlarm, 5000); // Check every 5 seconds for real-time demo accuracy
        return () => clearInterval(interval);
    }, [meds, activeAlarm]);

    const handleAddTime = () => {
        if (newTime && !addedTimes.includes(newTime)) {
            setAddedTimes([...addedTimes, newTime]);
            setNewTime('');
        }
    };

    const toggleDay = (dayIdx) => {
        if (selectedDays.includes(dayIdx)) {
            setSelectedDays(selectedDays.filter(d => d !== dayIdx));
        } else {
            setSelectedDays([...selectedDays, dayIdx].sort());
        }
    };

    const handleImageUpload = (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setNewImage(reader.result);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSaveMedication = () => {
        if (!newName || addedTimes.length === 0 || selectedDays.length === 0) {
            alert(isRtl ? 'يرجى إدخال اسم الدواء والمواعيد على الأقل' : 'Please enter medication name and times at least');
            return;
        }

        const newMed = {
            id: Date.now(),
            name: newName,
            image: newImage,
            dose: newDose || '1 pill',
            times: addedTimes.sort(),
            days: selectedDays,
            takenToday: false,
            color: `hsl(${Math.random() * 360}, 70%, 50%)`
        };

        setMeds([...meds, newMed]);
        setShowAddForm(false);

        // Reset form
        setNewName(''); setNewImage(null); setNewDose(''); setAddedTimes([]); setSelectedDays([0, 1, 2, 3, 4, 5, 6]);
    };

    const stopAudio = (alarm) => {
        if (alarm && alarm.audio) {
            alarm.audio.pause();
            alarm.audio.currentTime = 0;
        }
    };

    const markAsTaken = (id) => {
        setMeds(meds.map(m => m.id === id ? { ...m, takenToday: true } : m));
        if (activeAlarm && activeAlarm.id === id) {
            stopAudio(activeAlarm);
            setActiveAlarm(null);
        }
    };

    const handleSnooze = () => {
        if (activeAlarm) {
            stopAudio(activeAlarm);
            setActiveAlarm(null);
        }
    };

    const cancelAlarm = (id) => {
        // Stop audio if it's the active alarm
        if (activeAlarm && activeAlarm.id === id) {
            stopAudio(activeAlarm);
            setActiveAlarm(null);
        }
        // Remove the medication entirely
        setMeds(prev => prev.filter(m => m.id !== id));
    };

    return (
        <div className="flex flex-col gap-lg" style={{ paddingBottom: 100 }}>
            {/* Alarm Modal Overlay */}
            <AnimatePresence>
                {activeAlarm && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="flex flex-col items-center justify-center p-md text-center"
                        style={{
                            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
                            background: 'rgba(250, 82, 82, 0.95)', zIndex: 1000, color: 'white'
                        }}
                    >
                        <motion.div animate={{ scale: [1, 1.2, 1] }} transition={{ repeat: Infinity, duration: 1 }}>
                            <BellRing size={80} color="white" style={{ marginBottom: 20 }} />
                        </motion.div>
                        <h1 style={{ color: 'white', fontSize: '2.5rem', marginBottom: 10 }}>{isRtl ? 'موعد الدواء!' : 'Medication Time!'}</h1>

                        {activeAlarm.image && (
                            <img src={activeAlarm.image} alt="Medication" style={{ width: 140, height: 140, objectFit: 'cover', borderRadius: '20px', border: '4px solid white', marginBottom: 16 }} />
                        )}
                        <h2 style={{ color: 'white', fontSize: '2rem', marginBottom: 16 }}>{activeAlarm.name}</h2>

                        <p style={{ fontSize: '1.2rem', marginBottom: 40, opacity: 0.9 }}>
                            {isRtl ? `الجرعة المحددة: ${activeAlarm.dose}` : `Dose: ${activeAlarm.dose}`}
                        </p>

                        <div className="flex flex-col gap-md" style={{ width: '100%', maxWidth: 300 }}>
                            <button
                                onClick={() => markAsTaken(activeAlarm.id)}
                                className="btn-primary flex justify-center items-center gap-sm"
                                style={{ background: 'white', color: 'var(--danger)', fontSize: '1.2rem', padding: 20 }}
                            >
                                <CheckCircle2 size={28} /> {isRtl ? 'تم أخذ الدواء' : 'Taken'}
                            </button>

                            <button
                                onClick={handleSnooze}
                                className="btn-secondary flex justify-center items-center gap-sm"
                                style={{ background: 'transparent', border: '2px solid white', color: 'white', fontSize: '1.2rem', padding: 20 }}
                            >
                                {isRtl ? 'ذكرني لاحقاً (غفوة)' : 'Snooze'}
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <div className="flex justify-between items-center" style={{ padding: '10px 0' }}>
                <div>
                    <h2>{isRtl ? 'مواعيد الأدوية' : 'Medications'}</h2>
                    <p className="text-sm">{isRtl ? 'نظام التنبيهات الدقيق للأدوية.' : 'Precise medication alarms.'}</p>
                </div>
                <button className="btn-primary flex items-center justify-center" style={{ width: 44, height: 44, padding: 0, borderRadius: '50%' }} onClick={() => setShowAddForm(true)}>
                    <Plus size={24} />
                </button>
            </div>

            {/* Add Medication Form / Modal */}
            <AnimatePresence>
                {showAddForm && (
                    <motion.div
                        initial={{ opacity: 0, y: 100 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 100 }}
                        className="glass-panel"
                        style={{
                            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, zIndex: 500,
                            borderRadius: 0, overflowY: 'auto', padding: 20, paddingTop: 40,
                            background: 'var(--glass-bg)', backdropFilter: 'blur(20px)'
                        }}
                    >
                        <div className="flex justify-between items-center" style={{ marginBottom: 30 }}>
                            <h2 style={{ margin: 0 }}>{isRtl ? 'إضافة دواء جديد' : 'Add Medication'}</h2>
                            <button onClick={() => setShowAddForm(false)} style={{ background: 'var(--danger)', color: 'white', border: 'none', borderRadius: '50%', width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}>
                                <X size={20} />
                            </button>
                        </div>

                        <div className="flex flex-col gap-lg">
                            <input
                                type="text"
                                placeholder={isRtl ? 'اسم الدواء (مطلوب)' : 'Medication Name (Required)'}
                                value={newName}
                                onChange={(e) => setNewName(e.target.value)}
                            />

                            <div className="glass-card flex flex-col items-center justify-center p-md" style={{ border: '2px dashed var(--glass-border)', padding: 24, position: 'relative' }}>
                                {newImage ? (
                                    <img src={newImage} alt="Preview" style={{ width: '100%', height: 160, objectFit: 'cover', borderRadius: 12 }} />
                                ) : (
                                    <>
                                        <Camera size={36} color="var(--text-muted)" style={{ marginBottom: 12 }} />
                                        <p style={{ color: 'var(--text-muted)', textAlign: 'center', fontSize: '0.9rem' }}>
                                            {isRtl ? 'صورة الدواء (اختياري، اضغط للرفع)' : 'Medication Image (Optional, click to upload)'}
                                        </p>
                                    </>
                                )}
                                <input type="file" accept="image/*" capture="environment" onChange={handleImageUpload} style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', opacity: 0, cursor: 'pointer' }} />
                                {newImage && (
                                    <button onClick={(e) => { e.preventDefault(); setNewImage(null); }} style={{ position: 'absolute', top: 10, right: 10, background: 'rgba(0,0,0,0.5)', color: 'white', border: 'none', borderRadius: '50%', width: 28, height: 28 }}>
                                        <X size={16} />
                                    </button>
                                )}
                            </div>

                            <input
                                type="text"
                                placeholder={isRtl ? 'الجرعة (مثال: حبة واحدة, 10 مل)' : 'Dose (e.g., 1 pill, 10ml)'}
                                value={newDose}
                                onChange={(e) => setNewDose(e.target.value)}
                            />

                            {/* Times Selection */}
                            <div className="glass-card" style={{ padding: 20 }}>
                                <label style={{ display: 'block', marginBottom: 10, fontWeight: 'bold' }}>{isRtl ? 'أوقات الجرعة اليومية:' : 'Daily Dose Times:'}</label>
                                <div className="flex gap-md" style={{ marginBottom: 16 }}>
                                    <input type="time" value={newTime} onChange={(e) => setNewTime(e.target.value)} style={{ flex: 1 }} />
                                    <button className="btn-primary flex items-center justify-center" style={{ padding: '0 20px' }} onClick={handleAddTime}>
                                        <Plus size={20} />
                                    </button>
                                </div>

                                {addedTimes.length > 0 && (
                                    <div className="flex gap-sm flex-wrap">
                                        {addedTimes.map((time, idx) => (
                                            <span key={idx} className="glass-card flex items-center gap-sm" style={{ padding: '8px 16px', borderRadius: 20, background: 'var(--primary)', color: 'white', border: 'none' }}>
                                                <Clock size={16} /> {time}
                                                <X size={16} onClick={() => setAddedTimes(addedTimes.filter(t => t !== time))} style={{ cursor: 'pointer', marginLeft: 8 }} />
                                            </span>
                                        ))}
                                    </div>
                                )}
                            </div>

                            {/* Days Selection */}
                            <div className="glass-card" style={{ padding: 20 }}>
                                <label style={{ display: 'block', marginBottom: 16, fontWeight: 'bold' }}>{isRtl ? 'في أي أيام الأسبوع؟' : 'Days of the week?'}</label>
                                <div className="flex gap-sm justify-between">
                                    {weekDays.map((day, idx) => {
                                        const isSelected = selectedDays.includes(idx);
                                        return (
                                            <button
                                                key={idx}
                                                onClick={() => toggleDay(idx)}
                                                style={{
                                                    width: 40, height: 40, borderRadius: '50%', border: 'none',
                                                    background: isSelected ? 'var(--primary)' : 'var(--glass-bg)',
                                                    color: isSelected ? 'white' : 'var(--text-muted)',
                                                    fontWeight: 'bold', fontSize: '0.8rem', cursor: 'pointer',
                                                    boxShadow: isSelected ? '0 4px 12px rgba(12,166,120,0.4)' : 'none',
                                                    transition: 'all 0.2s'
                                                }}
                                            >
                                                {day[0]}
                                            </button>
                                        )
                                    })}
                                </div>
                            </div>

                            <button className="btn-primary" onClick={handleSaveMedication} style={{ padding: '16px', fontSize: '1.1rem', marginTop: 10 }}>
                                {isRtl ? 'حفظ الميعاد وتفعيل المنبه' : 'Save & Activate Alarm'}
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Medication List */}
            <div className="flex flex-col gap-md">
                <AnimatePresence>
                    {meds.length === 0 && (
                        <div className="glass-card flex flex-col justify-center items-center text-center p-lg text-muted" style={{ padding: 40 }}>
                            <Bell size={48} color="var(--glass-border)" style={{ marginBottom: 16 }} />
                            <p>{isRtl ? 'لم تقم بتسجيل أي أدوية بعد.' : 'No medications recorded yet.'}</p>
                        </div>
                    )}

                    {meds.map(med => (
                        <motion.div
                            layout
                            key={med.id}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            className={`glass-card flex flex-col justify-between`}
                            style={{
                                padding: 20,
                                borderRight: isRtl ? `6px solid ${med.color}` : 'none',
                                borderLeft: !isRtl ? `6px solid ${med.color}` : 'none',
                                position: 'relative',
                                opacity: med.takenToday ? 0.6 : 1
                            }}
                        >
                            <div className="flex justify-between items-start" style={{ marginBottom: 16 }}>
                                <div className="flex items-start gap-md">
                                    {med.image ? (
                                        <img src={med.image} alt="Medication" style={{ width: 60, height: 60, borderRadius: 12, objectFit: 'cover' }} />
                                    ) : (
                                        <div style={{ padding: 12, background: `${med.color}20`, borderRadius: 12, width: 60, height: 60, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                                            <Pill color={med.color} size={32} />
                                        </div>
                                    )}

                                    <div style={{ marginTop: 4 }}>
                                        <h2 style={{ margin: 0, fontSize: '1.2rem', textDecoration: med.takenToday ? 'line-through' : 'none' }}>{med.name}</h2>
                                        <span className="font-bold text-sm" style={{ color: 'var(--text-muted)' }}>{med.dose}</span>
                                    </div>
                                </div>

                                <button
                                    onClick={() => markAsTaken(med.id)}
                                    style={{
                                        background: med.takenToday ? 'var(--success)' : 'var(--glass-bg)',
                                        border: '1px solid var(--glass-border)',
                                        borderRadius: '50%',
                                        width: 44, height: 44,
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        cursor: 'pointer',
                                        boxShadow: med.takenToday ? '0 4px 12px rgba(64,192,87,0.4)' : 'none',
                                        transition: 'all 0.3s'
                                    }}
                                >
                                    <CheckCircle2 color={med.takenToday ? 'white' : 'var(--text-main)'} size={24} />
                                </button>
                            </div>

                            <div className="flex gap-sm" style={{ marginTop: 14 }}>
                                <button
                                    onClick={() => markAsTaken(med.id)}
                                    disabled={med.takenToday}
                                    className="btn-primary flex items-center justify-center gap-sm"
                                    style={{
                                        flex: 1, padding: '10px 12px', fontSize: '0.85rem', borderRadius: 12,
                                        background: med.takenToday ? 'var(--success)' : 'var(--primary)',
                                        opacity: med.takenToday ? 0.8 : 1
                                    }}
                                >
                                    <CheckCircle2 size={18} />
                                    {med.takenToday ? (isRtl ? '\u062aم \u0627\u0644\u0623\u062e\u0630' : 'Taken') : (isRtl ? '\u062a\u0645 \u0627\u0644\u0623\u062e\u0630' : 'Mark Taken')}
                                </button>
                                <button
                                    onClick={() => cancelAlarm(med.id)}
                                    title={isRtl ? '\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0645\u0646\u0628\u0647' : 'Cancel Alarm'}
                                    style={{
                                        background: 'rgba(239,68,68,0.1)', border: '1.5px solid rgba(239,68,68,0.3)',
                                        borderRadius: 12, padding: '10px 14px', cursor: 'pointer',
                                        color: 'var(--danger)', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                                        fontSize: '0.82rem', fontWeight: 600
                                    }}
                                >
                                    <BellOff size={17} />
                                    {isRtl ? '\u0625\u0644\u063a\u0627\u0621' : 'Cancel'}
                                </button>
                            </div>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, User, Activity, AlertCircle, Heart, Droplet, Thermometer, Wind, MessageCircle, Send, X, Clock, FileText, CheckCircle, XCircle } from 'lucide-react';

export default function PatientsList() {
    const navigate = useNavigate();
    const lang = document.documentElement.lang || 'ar';
    const isRtl = lang === 'ar';

    const [patients, setPatients] = useState([]);
    const [pendingRequests, setPendingRequests] = useState([]);

    const [selectedPatient, setSelectedPatient] = useState(null);
    const [messages, setMessages] = useState([]);
    const [chatInput, setChatInput] = useState('');

    const token = localStorage.getItem('token') || '';

    // Load actual data from API if available, else mock data fallback
    useEffect(() => {
        if (!token) {
            // Mock fallback
            setTimeout(() => {
                setPatients([
                    { id: 'p1', _id: 'p1', name: isRtl ? 'أحمد علي' : 'Ahmed Ali', age: 65, condition: isRtl ? 'سكري، ضغط دم' : 'Diabetes, Hypertension', status: 'critical', lastUpdate: isRtl ? 'منذ ١٠ دقائق' : '10 mins ago', vitals: { hr: 110, bp: '150/95', bg: 180, temp: 37.8, spo2: 94 } },
                    { id: 'p2', _id: 'p2', name: isRtl ? 'فاطمة سعد' : 'Fatima Saad', age: 54, condition: isRtl ? 'ربو' : 'Asthma', status: 'stable', lastUpdate: isRtl ? 'منذ ساعة' : '1 hour ago', vitals: { hr: 75, bp: '120/80', bg: 95, temp: 36.8, spo2: 98 } }
                ]);
                setPendingRequests([
                    { connId: 'c1', name: isRtl ? 'محمد خالد' : 'Mohammed Khaled' }
                ]);
            }, 0);
            return;
        }

        fetch('http://localhost:5000/api/connections/get_doctor_patients', {
            headers: { 'Authorization': `Bearer ${token}` }
        })
            .then(res => res.json())
            .then(data => {
                if (data && data.data) {
                    const approved = data.data.filter(c => c.status === 'approved').map(c => ({
                        ...c.patient_id, connId: c._id,
                        status: 'stable', condition: 'Under Observation',
                        vitals: { hr: 75, bp: '120/80', bg: 95, temp: 36.8, spo2: 98 },
                        lastUpdate: 'Just now'
                    }));
                    const pending = data.data.filter(c => c.status === 'pending').map(c => ({
                        connId: c._id,
                        name: c.patient_id?.name || 'Unknown Patient'
                    }));

                    setPatients(approved);
                    setPendingRequests(pending);
                }
            }).catch(err => console.error(err));
    }, [token, isRtl]);

    const handleAction = async (connId, action) => {
        try {
            if (!token) {
                // Mock behavior
                setPendingRequests(prev => prev.filter(r => r.connId !== connId));
                if (action === 'approve') {
                    setPatients(prev => [...prev, { id: Date.now(), _id: Date.now(), name: 'New Patient', age: 40, condition: 'General', status: 'stable', vitals: { hr: 75, bp: '120/80', bg: 95, temp: 36.8, spo2: 98 }, lastUpdate: 'Just now' }]);
                }
                return;
            }

            const res = await fetch(`http://localhost:5000/api/connections/${action}_follow_request/${connId}`, {
                method: 'PUT',
                headers: { 'Authorization': `Bearer ${token}` }
            });

            if (res.ok) {
                // Remove from pending
                const reqItem = pendingRequests.find(r => r.connId === connId);
                setPendingRequests(prev => prev.filter(r => r.connId !== connId));

                if (action === 'approve' && reqItem) {
                    // Refetch data optimally instead of full reload or hard mock
                    window.location.reload(); // Quick sync for simplicity
                }
            }
        } catch (error) {
            console.error(error);
        }
    };

    const openPatient = (patient) => {
        setSelectedPatient(patient);
        setMessages([
            { id: 1, sender: 'patient', text: isRtl ? 'مرحباً دكتور، أشعر ببعض التعب اليوم.' : 'Hello Doctor, I feel a bit tired today.', time: '10:00 AM' },
            { id: 2, sender: 'doctor', text: isRtl ? 'أهلاً بك. هل التزمت بمواعيد الدواء المحددة؟' : 'Welcome. Did you stick to the prescribed medication schedule?', time: '10:05 AM' }
        ]);
    };

    const handleSendMessage = () => {
        if (!chatInput.trim()) return;
        setMessages(prev => [...prev, {
            id: Date.now(),
            sender: 'doctor',
            text: chatInput,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }]);
        setChatInput('');
    };

    return (
        <div className="flex flex-col gap-lg" style={{ paddingBottom: 40 }}>
            <div className="flex justify-between items-center" style={{ padding: '10px 0' }}>
                <div>
                    <h2>{isRtl ? 'مرضاي والطلبات' : 'Patients & Requests'}</h2>
                    <p className="text-sm text-muted">{isRtl ? 'إدارة مرضاك النشطين ومعالجة الطلبات الجديدة.' : 'Manage your active patients and handle new medical requests.'}</p>
                </div>
            </div>

            {/* PENDING REQUESTS SECTION */}
            {pendingRequests.length > 0 && (
                <div className="flex flex-col gap-md">
                    <h3 style={{ margin: 0, fontSize: '1.2rem', color: 'var(--warning)' }}>
                        {isRtl ? 'طلبات متابعة معلقة' : 'Pending Follow-up Requests'}
                    </h3>
                    <div className="grid gap-sm">
                        {pendingRequests.map(req => (
                            <div key={req.connId} className="glass-card flex justify-between items-center" style={{ padding: 16, borderLeft: '4px solid var(--warning)' }}>
                                <div className="flex items-center gap-md">
                                    <User size={20} color="var(--warning)" />
                                    <span style={{ fontWeight: 600 }}>{req.name}</span>
                                </div>
                                <div className="flex gap-sm">
                                    <button onClick={() => handleAction(req.connId, 'approve')} className="flex items-center justify-center" style={{ background: '#e6f4ea', color: '#137333', border: 'none', borderRadius: 8, padding: '8px 12px', cursor: 'pointer', fontWeight: 'bold' }}>
                                        <CheckCircle size={18} style={{ marginRight: isRtl ? 0 : 4, marginLeft: isRtl ? 4 : 0 }} />
                                        {isRtl ? 'قبول' : 'Accept'}
                                    </button>
                                    <button onClick={() => handleAction(req.connId, 'reject')} className="flex items-center justify-center" style={{ background: '#fce8e6', color: '#c5221f', border: 'none', borderRadius: 8, padding: '8px 12px', cursor: 'pointer', fontWeight: 'bold' }}>
                                        <XCircle size={18} style={{ marginRight: isRtl ? 0 : 4, marginLeft: isRtl ? 4 : 0 }} />
                                        {isRtl ? 'رفض' : 'Reject'}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div style={{ position: 'relative' }}>
                <input
                    type="text"
                    placeholder={isRtl ? 'البحث في مرضاك...' : 'Search your patients...'}
                    style={{ paddingLeft: isRtl ? 16 : 40, paddingRight: isRtl ? 40 : 16, borderRadius: 12, border: '1px solid var(--glass-border)', background: 'var(--glass-bg)', width: '100%', color: 'var(--text-main)', padding: '12px' }}
                />
                <Search size={20} color="var(--text-muted)" style={{ position: 'absolute', right: isRtl ? 12 : 'auto', left: isRtl ? 'auto' : 12, top: 12 }} />
            </div>

            <div className="flex flex-col gap-md">
                <h3 style={{ margin: 0, fontSize: '1.2rem' }}>{isRtl ? 'المرضى الحاليون' : 'Active Patients'}</h3>
                {patients.length === 0 && <p className="text-sm text-muted">{isRtl ? 'لا يوجد مرضى حاليين لتتم متابعتهم.' : 'No active patients to follow up on.'}</p>}

                {patients.map(p => (
                    <motion.div
                        key={p._id || p.id}
                        onClick={() => openPatient(p)}
                        whileTap={{ scale: 0.98 }}
                        className="glass-card"
                        style={{
                            padding: 16,
                            borderLeft: p.status === 'critical' ? '4px solid var(--danger)' : p.status === 'warning' ? '4px solid var(--warning)' : '4px solid var(--success)',
                            cursor: 'pointer'
                        }}
                    >
                        <div className="flex justify-between items-start">
                            <div className="flex items-center gap-md">
                                <div style={{ background: 'var(--glass-bg)', padding: 10, borderRadius: '50%' }}>
                                    <User size={24} color="var(--text-main)" />
                                </div>
                                <div>
                                    <h3 style={{ margin: 0, fontSize: '1.1rem' }}>{p.name}</h3>
                                    <p className="text-sm">{p.age} {isRtl ? 'سنة' : 'yrs'} • {p.condition}</p>
                                </div>
                            </div>

                            {p.status === 'critical' ? (
                                <AlertCircle color="var(--danger)" size={24} />
                            ) : (
                                <Activity color={p.status === 'warning' ? 'var(--warning)' : 'var(--success)'} size={24} />
                            )}
                        </div>

                        <div style={{ marginTop: 12, paddingTop: 12, borderTop: '1px solid var(--glass-border)', fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                            {isRtl ? 'آخر مزامنة:' : 'Last data sync:'} {p.lastUpdate}
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Patient Details & Chat Modal */}
            <AnimatePresence>
                {selectedPatient && (
                    <motion.div
                        initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 50 }}
                        style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100dvh', background: 'var(--bg-main)', zIndex: 999, display: 'flex', flexDirection: 'column' }}
                    >
                        {/* Header */}
                        <div className="glass-panel" style={{ padding: '20px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderRadius: 0, borderBottom: '1px solid var(--glass-border)' }}>
                            <div className="flex items-center gap-md">
                                <div style={{ background: 'var(--primary)', color: 'white', padding: 8, borderRadius: '50%' }}>
                                    <User size={24} />
                                </div>
                                <div className="flex flex-col">
                                    <h2 style={{ margin: 0, fontSize: '1.2rem' }}>{selectedPatient.name}</h2>
                                    <span className="text-sm text-muted">{selectedPatient.condition}</span>
                                </div>
                            </div>
                            <button onClick={() => setSelectedPatient(null)} style={{ background: 'transparent', border: 'none', color: 'var(--text-main)', cursor: 'pointer' }}>
                                <X size={28} />
                            </button>
                        </div>

                        {/* Content Area */}
                        <div style={{ flex: 1, overflowY: 'auto', padding: 16 }}>

                            {/* Vitals Section */}
                            <div className="flex justify-between items-center" style={{ marginBottom: 12 }}>
                                <h3 style={{ margin: 0 }}>{isRtl ? 'المؤشرات الحيوية الأخيرة' : 'Latest Vitals'}</h3>
                                <button
                                    className="btn-primary flex items-center gap-sm"
                                    style={{ padding: '6px 12px', fontSize: '0.8rem', borderRadius: 12 }}
                                    onClick={() => navigate('/reports', { state: { patient: selectedPatient } })}
                                >
                                    <FileText size={16} />
                                    {isRtl ? 'عرض التقرير' : 'View Report'}
                                </button>
                            </div>
                            <div className="grid grid-cols-2" style={{ gap: 12, marginBottom: 24 }}>
                                <div className="glass-card flex items-center gap-sm" style={{ padding: 12 }}>
                                    <Heart color="var(--danger)" size={20} />
                                    <div className="flex flex-col">
                                        <span className="text-sm text-muted">{isRtl ? 'النبض' : 'Heart Rate'}</span>
                                        <span className="font-bold">{selectedPatient.vitals.hr} bpm</span>
                                    </div>
                                </div>
                                <div className="glass-card flex items-center gap-sm" style={{ padding: 12 }}>
                                    <Activity color="var(--warning)" size={20} />
                                    <div className="flex flex-col">
                                        <span className="text-sm text-muted">{isRtl ? 'الضغط' : 'Blood Pressure'}</span>
                                        <span className="font-bold">{selectedPatient.vitals.bp}</span>
                                    </div>
                                </div>
                                <div className="glass-card flex items-center gap-sm" style={{ padding: 12 }}>
                                    <Droplet color="#339af0" size={20} />
                                    <div className="flex flex-col">
                                        <span className="text-sm text-muted">{isRtl ? 'السكر' : 'Glucose'}</span>
                                        <span className="font-bold">{selectedPatient.vitals.bg} mg/dL</span>
                                    </div>
                                </div>
                                <div className="glass-card flex items-center gap-sm" style={{ padding: 12 }}>
                                    <Wind color="var(--success)" size={20} />
                                    <div className="flex flex-col">
                                        <span className="text-sm text-muted">{isRtl ? 'الأكسجين' : 'SpO2'}</span>
                                        <span className="font-bold">{selectedPatient.vitals.spo2}%</span>
                                    </div>
                                </div>
                                <div className="glass-card flex items-center gap-sm" style={{ padding: 12, gridColumn: 'span 2' }}>
                                    <Thermometer color="var(--primary)" size={20} />
                                    <div className="flex flex-col">
                                        <span className="text-sm text-muted">{isRtl ? 'درجة الحرارة' : 'Body Temp'}</span>
                                        <span className="font-bold">{selectedPatient.vitals.temp}°C</span>
                                    </div>
                                </div>
                            </div>

                            {/* Chat Section */}
                            <div className="flex items-center gap-sm" style={{ marginBottom: 16 }}>
                                <MessageCircle color="var(--primary)" size={20} />
                                <h3 style={{ margin: 0 }}>{isRtl ? 'المحادثة' : 'Chat'}</h3>
                            </div>

                            <div className="flex flex-col gap-md" style={{ paddingBottom: 80 }}>
                                {messages.map(msg => {
                                    const isMe = msg.sender === 'doctor';
                                    return (
                                        <div key={msg.id} style={{ display: 'flex', flexDirection: 'column', alignItems: isMe ? (isRtl ? 'flex-end' : 'flex-end') : (isRtl ? 'flex-start' : 'flex-start') }}>
                                            <div
                                                className="glass-card"
                                                style={{
                                                    padding: '12px 16px',
                                                    maxWidth: '80%',
                                                    background: isMe ? 'var(--primary)' : 'var(--glass-bg)',
                                                    color: isMe ? 'white' : 'var(--text-main)',
                                                    borderRadius: isMe ? (isRtl ? '20px 0 20px 20px' : '20px 20px 0 20px') : (isRtl ? '0 20px 20px 20px' : '20px 20px 20px 0'),
                                                    border: isMe ? 'none' : '1px solid var(--glass-border)'
                                                }}
                                            >
                                                <p style={{ margin: 0, fontSize: '0.95rem', lineHeight: 1.5 }}>{msg.text}</p>
                                            </div>
                                            <div className="flex items-center gap-sm text-muted" style={{ fontSize: '0.75rem', marginTop: 4 }}>
                                                <Clock size={12} /> {msg.time}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                        </div>

                        {/* Chat Input */}
                        <div className="glass-panel" style={{ padding: 16, borderTop: '1px solid var(--glass-border)', display: 'flex', gap: 12, borderRadius: 0 }}>
                            <input
                                type="text"
                                placeholder={isRtl ? 'اكتب رسالة...' : 'Type a message...'}
                                value={chatInput}
                                onChange={e => setChatInput(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                                style={{ flex: 1, background: 'var(--glass-bg)', border: '1px solid var(--glass-border)', borderRadius: 24, padding: '12px 20px', color: 'var(--text-main)' }}
                            />
                            <button
                                onClick={handleSendMessage}
                                style={{ background: 'var(--primary)', color: 'white', border: 'none', borderRadius: '50%', width: 48, height: 48, display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}
                            >
                                <Send size={20} style={{ transform: isRtl ? 'rotate(180deg)' : 'none', marginRight: isRtl ? 0 : 4, marginLeft: isRtl ? 4 : 0 }} />
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

